"use client"

import * as React from "react"

import { Cancel01Icon } from "@hugeicons/core-free-icons"
import { HugeiconsIcon } from "@hugeicons/react"

import { cn } from "@/lib/utils"
import { Icon, type IconName } from "@/components/ui/icon"

import { useAmbientRuntime } from "./ambient-runtime"
import { useAssistant, type ContextChip } from "./assistant-context"
import { OrbCharacter } from "./orb-character"

/**
 * THE SHARED MARKS — the small pieces the assistant's own input row wears.
 *
 * These lived in assistant.tsx, which is the 1,700-line surface shell. Only
 * composer.tsx used them, and that one import edge meant EVERY component in
 * the layer transitively required the entire surface: asking the registry for
 * a ReasoningPanel produced sixteen files, nearly the whole package.
 *
 * Nothing here is new. They were always a separate thing — the shell just
 * happened to be where they were written. Splitting them costs nothing and
 * lets a kit be installed as a kit.
 */


/**
 * THE AI FORM'S PLACEHOLDER — the shimmer belongs to every ambient input,
 * not just the palette's: it is how a form says the assistant is listening.
 * Rendered as an overlay because an <input>'s own placeholder can't carry a
 * background-clipped gradient.
 */
export function ShimmerPlaceholder({
  show,
  children,
  className,
}: {
  show: boolean
  children: React.ReactNode
  className?: string
}) {
  if (!show) return null
  return (
    <span
      aria-hidden
      className={cn(
        // inset-0, not left-0: the ghost stands in for a single-line <input>,
        // so it must be bounded by the field's box and truncate the way the
        // input would. Unbounded, a long suggestion wrapped to two lines the
        // moment the scaling base grew (95% fit by luck; 100% did not).
        "ambient-shimmer pointer-events-none absolute inset-0 flex items-center text-base",
        className
      )}
    >
      <span className="truncate">{children}</span>
    </span>
  )
}


/**
 * The assistant's mark: the real OrbCharacter — one shader instance per
 * surface mark, riding the live ambient state. (The CSS OrbGlyph remains
 * for incidental marks: the footer brand and settled transcript entries,
 * where a context per row would stack up — DESIGN.md §12.)
 */
export function AssistantMark({ size }: { size: number }) {
  const runtime = useAmbientRuntime()
  const { orbState } = useAssistant()
  return (
    <span className="inline-flex shrink-0">
      <OrbCharacter
        size={size}
        state={orbState}
        colors={runtime.orb.useAccent ? undefined : runtime.orb.colors}
        speeds={runtime.orb.speeds}
      />
    </span>
  )
}


/**
 * What each kind of context LOOKS like. Sparkles is gone from this map on
 * purpose: in this system sparkles means the ASSISTANT — its mark, AskAI,
 * the follow-up heading — and a context chip is not the assistant. It is the
 * thing the assistant can see, so it wears the icon of the thing.
 *
 * Names, not icon modules: these are drawn by whichever library the
 * Foundation has configured (rule 6), like every other icon in the product.
 */
const chipKindIcon: Record<ContextChip["kind"], IconName> = {
  page: "document",
  control: "sliders",
  target: "layers",
  cell: "layers",
  file: "code",
  symbol: "code",
  selection: "type",
}


export function IconTile({
  icon,
  compact,
}: {
  icon: IconName
  compact?: boolean
}) {
  return (
    <span
      className={cn(
        "flex shrink-0 items-center justify-center bg-[var(--ambient-accent-wash)] text-[var(--ambient-accent)]",
        compact ? "size-4 rounded-[4px]" : "size-5 rounded-[5px]"
      )}
    >
      <Icon name={icon} size={compact ? 10 : 12} />
    </span>
  )
}


/**
 * CONTEXT CHIP — one attachment the assistant will answer against: the page
 * itself, or anything the user right-clicked into the conversation.
 *
 * THE ANATOMY IS ONE OBJECT, not a per-surface treatment: icon tile (typed by
 * what was attached) · label · a squared remove control. Two sizes only —
 * `default` where the composer has a row of its own (palette, panel), and
 * `compact` where chips share a line with the input (quick ask). Nothing
 * else varies; a surface picks the size, never the look.
 */
export function ContextChipView({
  chip,
  compact,
  onRemove,
  className,
}: {
  chip: ContextChip
  compact?: boolean
  onRemove?: () => void
  className?: string
}) {
  return (
    <span
      className={cn(
        // shrink-0: these ride in a scrolling slider, where a flex child that
        // shrinks squeezes instead of scrolling and every chip loses its label
        "inline-flex max-w-full shrink-0 items-center rounded-lg border border-border bg-(--wash) font-medium",
        compact
          ? "gap-1.5 py-0.5 ps-1 pe-0.5 text-[11.5px]"
          : "gap-2 py-1 ps-1.5 pe-1 text-[12.5px]",
        className
      )}
    >
      {/* the chip's own icon when it has one — the page knows what it is */}
      <IconTile icon={chip.icon ?? chipKindIcon[chip.kind]} compact={compact} />
      <span className="max-w-56 min-w-0 truncate">{chip.label}</span>
      {onRemove && (
        <button
          type="button"
          aria-label={`Remove ${chip.label}`}
          onClick={onRemove}
          className={cn(
            "flex shrink-0 items-center justify-center rounded-md bg-accent text-muted-foreground hover:text-foreground",
            compact ? "size-[18px]" : "size-[22px]"
          )}
        >
          <HugeiconsIcon
            icon={Cancel01Icon}
            size={compact ? 11 : 13}
            strokeWidth={1.8}
          />
        </button>
      )}
    </span>
  )
}

/* eslint-disable react-refresh/only-export-components --
   Same shape, same reason as foundation-context.tsx: one concept's contract,
   defaults, provider and hooks belong in one module. Splitting them to satisfy
   Fast Refresh would put the interface in one file and its only implementation
   in another, for a dev-ergonomics win on a file that changes rarely. */
"use client"

import * as React from "react"

import { DEFAULT_STATE_SPEEDS, type OrbState } from "./kit-vocabulary"

/**
 * THE AMBIENT LAYER'S RUNTIME — everything it needs from a design system, and
 * nothing else.
 *
 * The layer used to read the Foundation directly. That was correct while both
 * lived in one app and fatal the moment anyone wanted the layer without it:
 * eight files importing `@/foundation/foundation-context` is eight hard
 * dependencies on 792 lines of configurator, to consume seven values.
 *
 * So the dependency is inverted. This file states the contract; the Foundation
 * *implements* it (see the bridge in foundation-context.tsx). The layer now
 * asks for what it needs rather than reaching for where it happens to live.
 *
 * THE CONTEXT HAS A REAL DEFAULT AND THE HOOK NEVER THROWS. That is the whole
 * point, and the deliberate opposite of `useFoundation()`, which throws
 * outside its provider. `<Assistant />` mounted in a bare app must render and
 * animate correctly on these values — if it ever cannot, this file is wrong,
 * not the app.
 *
 * The defaults below are not invented. They mirror two existing sources and
 * must keep mirroring them:
 *   · the motion numbers = the "productive" character in foundation-context.tsx
 *     and the `--motion-*` block in packages/ui globals.css (both 120/180/240/
 *     320ms on cubic-bezier(0.2, 0, 0, 1))
 *   · the orb cadence = DEFAULT_STATE_SPEEDS, imported rather than restated
 * Two copies of one value is this project's named failure mode; where a copy is
 * unavoidable, the comment naming the other copy is the mitigation.
 */

export type MotionRole = "micro" | "control" | "surface" | "page"

export type AmbientEase = [number, number, number, number]

export type AmbientTransition = { duration: number; ease: AmbientEase }

export type AmbientSpring = {
  type: "spring"
  stiffness: number
  damping: number
}

export interface AmbientRuntime {
  /**
   * Where the layer's own static assets are served from — the orb's shader
   * shapes (orb-circle.svg and the rect family), which the registry installs
   * into the host's `public/`.
   *
   * It is a value rather than a hardcoded "/" because a site served from a
   * subpath (GitHub Pages project sites, any app mounted under a prefix)
   * resolves a root-absolute URL against the DOMAIN, not the app — so the
   * shader silently loads nothing and the orb goes cold. Default "/" is
   * correct for an app at the root, which is most of them.
   */
  assetBase: string
  /** How a message is presented — see MessagePair. */
  messageVariant: "bubble" | "flat"
  /** The pace StreamingText types at. */
  streamCharsPerSecond: number
  /** The orb's palette and per-state cadence. */
  orb: {
    useAccent: boolean
    colors: string[]
    speeds: Record<OrbState, number>
  }
  /** The framer-motion tween for a motion role (DESIGN.md §5). */
  motionTransition: (role: MotionRole) => AmbientTransition
  /** The spring for interruptible/gestural motion. */
  motionSpring: () => AmbientSpring
}

/* Mirrors globals.css `:root` and the "productive" motion character. */
const DEFAULT_DURATIONS_MS: Record<MotionRole, number> = {
  micro: 120,
  control: 180,
  surface: 240,
  page: 320,
}
const DEFAULT_EASE: AmbientEase = [0.2, 0, 0, 1]

export const DEFAULT_AMBIENT_RUNTIME: AmbientRuntime = {
  assetBase: "/",
  messageVariant: "bubble",
  streamCharsPerSecond: 60,
  orb: {
    useAccent: true,
    colors: ["#8bd8ff", "#2563eb", "#0b1e55"],
    speeds: DEFAULT_STATE_SPEEDS,
  },
  motionTransition: (role) => ({
    duration: DEFAULT_DURATIONS_MS[role] / 1000,
    ease: DEFAULT_EASE,
  }),
  motionSpring: () => ({ type: "spring", stiffness: 380, damping: 32 }),
}

const AmbientRuntimeContext = React.createContext<AmbientRuntime>(
  DEFAULT_AMBIENT_RUNTIME
)

/**
 * Supplies a runtime. Anything omitted falls back to the default, so a host
 * can override the stream pace without knowing what a motion role is.
 */
export function AmbientRuntimeProvider({
  value,
  children,
}: {
  value?: Partial<AmbientRuntime>
  children: React.ReactNode
}) {
  const runtime = React.useMemo<AmbientRuntime>(
    () => (value ? { ...DEFAULT_AMBIENT_RUNTIME, ...value } : DEFAULT_AMBIENT_RUNTIME),
    [value]
  )
  return (
    <AmbientRuntimeContext.Provider value={runtime}>
      {children}
    </AmbientRuntimeContext.Provider>
  )
}

/** Never throws — see the header. A bare mount is a supported configuration. */
export function useAmbientRuntime() {
  return React.useContext(AmbientRuntimeContext)
}

/** The framer-motion tween for a motion role. */
export function useMotionTransition(role: MotionRole) {
  return useAmbientRuntime().motionTransition(role)
}

/** The configured character's spring. */
export function useMotionSpring() {
  return useAmbientRuntime().motionSpring()
}

/**
 * Resolve one of the layer's own assets against the host's base. Tolerates a
 * base with or without its trailing slash, because both spellings are common
 * and the failure (a doubled or missing slash) is silent.
 */
export function useAmbientAsset(file: string) {
  const base = useAmbientRuntime().assetBase
  return `${base.replace(/\/$/, "")}/${file.replace(/^\//, "")}`
}

/* eslint-disable react-refresh/only-export-components */
"use client"

import * as React from "react"

import type { IconName } from "@/components/ui/icon"

import type { OrbState } from "./orb-character"

export type AssistantMode =
  | "line"
  | "panel"
  | "dock"
  | "spotlight"
  | "history"

export type OrbAnchor = "tl" | "tc" | "tr" | "ml" | "mr" | "bl" | "bc" | "br"

export type ContextChip = {
  id: string
  label: string
  /**
   * What was attached. The kind picks the chip's mark and tells the composer
   * what sort of answer the question deserves — a file earns tool calls and a
   * diff, a page earns a search and citations.
   */
  kind: "page" | "control" | "target" | "cell" | "file" | "symbol" | "selection"
  /**
   * What this particular thing IS, when the kind is too coarse to say. Every
   * page is `kind: "page"`, but a page can be an editor, a colour map or a
   * motion table — and the page is the only thing that knows which. Omitted,
   * the kind's own icon stands in.
   */
  icon?: IconName
}

/**
 * What the page knows that the ambient layer should surface: the questions
 * worth asking RIGHT NOW (live — a healed problem leaves the list) and the
 * working history this surface would plausibly have. Announced by the page
 * like pageChip is; the layer renders it and falls back to its generic
 * defaults when no page has spoken.
 */
export type PageIntel = {
  suggestions?: string[]
  recents?: { text: string; when: string }[]
  /**
   * What "Jump to" navigates to while this page is open. A page with its own
   * workspace — the dev tool's files — offers those instead of the app's
   * routes: the palette should move you around where you are working, not
   * away from it.
   */
  jumps?: { id: string; label: string; desc?: string }[]
  onJump?: (id: string) => void
  /**
   * What the spotlight's input invites here. The generic line asks about the
   * app; a page with its own material can ask about that instead.
   */
  askPlaceholder?: string
  /** Section headings, when the page's own words are more useful. */
  suggestLabel?: string
  jumpLabel?: string
}

/**
 * A COMMAND the palette can run. The app registers these; the layer renders
 * them and calls `run`. It never learns what a command means — same contract
 * as the context chip, in the other direction.
 */
/**
 * A place the host app can navigate to, offered in the palette's "Jump to".
 *
 * THE LAYER IS TOLD, NEVER IMPORTS. assistant.tsx used to `import { sections }
 * from "@/nav"` — a UI layer reaching into one particular app's route table,
 * and the single thing that made it un-liftable. `icon` is deliberately
 * `unknown`: the layer only forwards it to the host's own Icon, so no icon
 * library leaks into the public contract.
 */
export type NavItem = {
  id: string
  label: string
  desc?: string
  icon?: unknown
}

export type AmbientCommand = {
  id: string
  /** The group heading it files under: "Components", "Documentation"… */
  section: string
  label: string
  desc?: string
  /** Extra words to match on that are not worth showing. */
  keywords?: string
  /** An icon NAME from the vocabulary, drawn by the configured library. */
  icon?: string
  run: () => void
}

type AssistantState = {
  mode: AssistantMode
  setMode: (m: AssistantMode) => void
  /** Ambient context — what the user is currently looking at. Replaced on navigation/selection. */
  pageChip: ContextChip | null
  setPageChip: (c: ContextChip | null) => void
  /** What the current page suggests and remembers — see PageIntel. */
  pageIntel: PageIntel | null
  setPageIntel: (i: PageIntel | null) => void
  /** Everything ⌘K can DO, registered by the app — see AmbientCommand. */
  commands: AmbientCommand[]
  setCommands: (c: AmbientCommand[]) => void
  /** Where the host can go — see NavItem. Empty is a valid state. */
  navItems: NavItem[]
  /** Explicit context added by the user (right-click → Explain / Add to context). */
  chips: ContextChip[]
  addChip: (c: ContextChip) => void
  removeChip: (id: string) => void
  /** Right-click → Explain: attach context and open the assistant with a seeded prompt. */
  explain: (c: ContextChip) => void
  seedVersion: number
  consumeSeededPrompt: () => string | null
  /**
   * Hand a prompt to the next surface. autoSend asks it on arrival;
   * immediate skips the thinking beat, for a surface that already showed it.
   */
  seedPrompt: (text: string, autoSend?: boolean, immediate?: boolean) => void
  /** True once, if the pending seed should be sent rather than typed. */
  consumeAutoSend: () => boolean
  /** True once, if the pending seed should compose without the thinking beat. */
  consumeImmediate: () => boolean
  orbAnchor: OrbAnchor
  setOrbAnchor: (a: OrbAnchor) => void
  /** The orb character's state — driven by the response pipeline. */
  orbState: OrbState
  setOrbState: (s: OrbState) => void
  /** Navigate the app shell to a section (wired by App). */
  navigate?: (sectionId: string) => void
  /**
   * The last workspace effect a settled answer announced. Surfaces that own
   * product state subscribe and decide what it means; the layer only relays.
   */
  workspaceEffect: string | null
  announceEffect: (effect: string | null) => void
}

const AssistantContext = React.createContext<AssistantState | undefined>(undefined)

export function AssistantProvider({
  children,
  onNavigate,
  navItems = [],
}: {
  children: React.ReactNode
  onNavigate?: (sectionId: string) => void
  navItems?: NavItem[]
}) {
  const [mode, setMode] = React.useState<AssistantMode>("line")
  const [pageChip, setPageChip] = React.useState<ContextChip | null>(null)
  const [pageIntel, setPageIntel] = React.useState<PageIntel | null>(null)
  const [commands, setCommands] = React.useState<AmbientCommand[]>([])
  const [chips, setChips] = React.useState<ContextChip[]>([])
  const [seedVersion, setSeedVersion] = React.useState(0)
  const [workspaceEffect, announceEffect] = React.useState<string | null>(null)
  const [orbAnchor, setOrbAnchor] = React.useState<OrbAnchor>("bc")
  const [orbState, setOrbState] = React.useState<OrbState>("still")
  const seededRef = React.useRef<string | null>(null)

  const addChip = React.useCallback((c: ContextChip) => {
    setChips((prev) => (prev.some((p) => p.id === c.id) ? prev : [...prev, c]))
  }, [])

  const removeChip = React.useCallback((id: string) => {
    setChips((prev) => prev.filter((c) => c.id !== id))
  }, [])

  const explain = React.useCallback(
    (c: ContextChip) => {
      addChip(c)
      seededRef.current = `Explain ${c.label}`
      setSeedVersion((v) => v + 1)
      setMode("panel")
    },
    [addChip]
  )

  const consumeSeededPrompt = React.useCallback(() => {
    const p = seededRef.current
    seededRef.current = null
    return p
  }, [])

  const autoSendRef = React.useRef(false)
  const immediateRef = React.useRef(false)
  const seedPrompt = React.useCallback(
    (text: string, autoSend = false, immediate = false) => {
      seededRef.current = text
      autoSendRef.current = autoSend
      immediateRef.current = immediate
      setSeedVersion((v) => v + 1)
    },
    []
  )
  const consumeAutoSend = React.useCallback(() => {
    const a = autoSendRef.current
    autoSendRef.current = false
    return a
  }, [])
  const consumeImmediate = React.useCallback(() => {
    const i = immediateRef.current
    immediateRef.current = false
    return i
  }, [])

  const value = React.useMemo(
    () => ({
      mode,
      setMode,
      pageChip,
      setPageChip,
      pageIntel,
      setPageIntel,
      commands,
      setCommands,
      chips,
      addChip,
      removeChip,
      explain,
      seedVersion,
      seedPrompt,
      consumeAutoSend,
      consumeImmediate,
      consumeSeededPrompt,
      orbAnchor,
      setOrbAnchor,
      orbState,
      setOrbState,
      navigate: onNavigate,
      navItems,
      workspaceEffect,
      announceEffect,
    }),
    [mode, pageChip, pageIntel, commands, chips, addChip, removeChip, explain, seedVersion, seedPrompt, consumeAutoSend, consumeImmediate, consumeSeededPrompt, orbAnchor, orbState, onNavigate, navItems, workspaceEffect]
  )

  return (
    <AssistantContext.Provider value={value}>
      {children}
    </AssistantContext.Provider>
  )
}

export function useAssistant() {
  const ctx = React.useContext(AssistantContext)
  if (!ctx) throw new Error("useAssistant must be used within AssistantProvider")
  return ctx
}

"use client"

import * as React from "react"

import { cn } from "@/lib/utils"

import { Button } from "@/components/ui/button"
import { Icon } from "@/components/ui/icon"

import {
  AssistantMark,
  ContextChipView,
  ShimmerPlaceholder,
} from "./ambient-marks"
import {
  MessageAttachments,
  type MessageAttachment,
} from "./message-kit"
import type { ContextChip } from "./assistant-context"

/**
 * THE COMPOSER — the one place a question is written, extracted so every
 * form factor shares a single anatomy: context chips · input · one control.
 *
 * ONE CONTROL, TWO MEANINGS. Send while idle, STOP while an answer is
 * composing or streaming — always the one that applies right now. (An orb
 * was tried in this slot and removed: the identity already lives in the
 * shell, and a character where a control belongs read as decoration, not
 * as an affordance.)
 *
 * Send only lights up once there is something to send: the affordance
 * states its own availability.
 *
 * `variant`: `panel` is the in-surface row (panel and dock); `quick` is the
 * same anatomy inside quick ask's pill — the pill supplies the glass and the
 * height, the composer supplies everything the user touches; `inline` is the
 * one that stands on its own inside another object (a review thread), so it
 * brings its own frame and sits at the smaller type size. The spotlight's
 * search-or-ask band is next.
 */
export type ComposerVariant = "panel" | "quick" | "inline"

export function Composer({
  inputRef,
  value,
  onChange,
  onSend,
  onStop,
  onEscape,
  busy = false,
  pageChip,
  chips = [],
  removeChip,
  placeholder,
  mark,
  suggestion,
  onAcceptSuggestion,
  attachments = [],
  onAttach,
  onPasteText,
  onRemoveAttachment,
  variant = "panel",
  className,
}: {
  inputRef?: React.RefObject<HTMLInputElement | null>
  value: string
  onChange: (v: string) => void
  onSend: () => void
  /** Interrupt the running answer. Shown only while `busy`. */
  onStop?: () => void
  /** Dismiss the surface (quick ask closes on Escape). */
  onEscape?: () => void
  /** An answer is composing or streaming — the orb yields to Stop. */
  busy?: boolean
  pageChip?: ContextChip | null
  chips?: ContextChip[]
  removeChip?: (id: string) => void
  placeholder: string
  /**
   * Show the assistant's character at the head of the row. It is an IDENTITY
   * MARK, not a control — it reacts (still / listening / thinking / answer)
   * so the row says who is listening, and it never takes the send slot,
   * where a character reads as decoration rather than an affordance.
   *
   * Defaults per variant rather than per caller: `panel` carries the mark
   * because it is the row that stands alone; `quick` does not, because the
   * orb it would duplicate is the pill it sits inside; `inline` does not,
   * because it belongs to the object hosting it. A caller that needs the
   * other answer says so, but no caller has to remember the usual one.
   */
  mark?: boolean
  /**
   * What to do next, offered in the empty field. Ghost text rather than a
   * button: it costs no room, and it is a proposal the user can type straight
   * over. Tab accepts it.
   */
  suggestion?: string
  /** Tab was pressed on the offer — run it. */
  onAcceptSuggestion?: () => void
  /** Staged attachments, shown above the row and removable until sent. */
  attachments?: MessageAttachment[]
  /**
   * A substantial paste became an attachment instead of filling the field.
   * Pasting a stack trace or a whole file into a one-line input buries the
   * question you were writing under material you only meant to REFER to — so
   * the material becomes context and the input stays yours.
   */
  onPasteText?: (text: string) => void
  onRemoveAttachment?: (id: string) => void
  /**
   * Attach something explicitly. It sits beside SEND rather than out with the
   * context chips because it makes the same kind of move the composer's other
   * controls do — it acts on the turn you are about to send, and the row you
   * are typing in is where you reach for that.
   */
  onAttach?: () => void
  variant?: ComposerVariant
  className?: string
}) {
  // an offer only stands while the field is empty: the moment the user types,
  // their own words win
  const offering = Boolean(suggestion && onAcceptSuggestion && value === "")
  const showMark = mark ?? variant === "panel"
  // What counts as "substantial": more than one line, or longer than a
  // sentence someone would have typed. A short paste is almost always part of
  // the question being written, and must stay in the field.
  const isBulk = (t: string) => t.includes("\n") || t.length > 180
  const row = (
    <div
      className={cn(
        "flex items-center gap-3",
        // panel: the row brings its own height. quick: the pill does.
        // inline: nothing else will, so it brings frame and padding too.
        variant === "panel" && "min-h-14",
        variant === "quick" && "h-full min-w-0 flex-1 gap-2",
        variant === "inline" &&
          "border-(--glass-border) w-full gap-2 rounded-lg border px-2.5 py-1",
        className
      )}
    >
      {showMark && <AssistantMark size={28} />}
      {pageChip && <ContextChipView chip={pageChip} compact />}
      {chips.map((c) => (
        <ContextChipView
          key={c.id}
          chip={c}
          compact
          onRemove={removeChip ? () => removeChip(c.id) : undefined}
        />
      ))}
      <div className="relative min-w-0 flex-1">
        <input
          ref={inputRef}
          value={value}
          onChange={(e) => onChange(e.target.value)}
          onKeyDown={(e) => {
            if (e.key === "Enter") onSend()
            if (e.key === "Escape") onEscape?.()
            // Tab accepts the offer — the shell's own convention for
            // completing something already proposed
            if (e.key === "Tab" && offering) {
              e.preventDefault()
              onAcceptSuggestion?.()
            }
          }}
          onPaste={(e) => {
            if (!onPasteText) return
            const text = e.clipboardData.getData("text")
            if (!isBulk(text)) return
            e.preventDefault()
            onPasteText(text)
          }}
          aria-label={placeholder}
          className={cn(
            "w-full bg-transparent outline-none",
            variant === "inline" ? "text-sm" : "text-base"
          )}
        />
        <ShimmerPlaceholder
          show={value === ""}
          className={variant === "inline" ? "text-sm" : undefined}
        >
          {offering ? suggestion : placeholder}
        </ShimmerPlaceholder>
      </div>
      {offering && (
        <kbd className="border-border text-muted-foreground pointer-events-none hidden shrink-0 rounded border px-1.5 py-0.5 font-mono text-xs sm:inline">
          Tab
        </kbd>
      )}

      {/* the sanctioned Button, both meanings: filled (primary) to send once
          there is text, outline to stop. Disabled states its availability.
          While busy WITH text, a third state: queue — the instruction stacks
          behind the running turn instead of interrupting it. */}
      {onAttach && (
        <Button
          type="button"
          size={variant === "inline" ? "icon-xs" : "icon-sm"}
          variant="ghost"
          aria-label="Attach context"
          title="Attach a file, a selection, or paste text"
          onClick={onAttach}
          className="text-muted-foreground hover:text-foreground shrink-0 rounded-full"
        >
          <Icon name="plus" size={variant === "inline" ? 13 : 15} />
        </Button>
      )}
      {busy && value.trim() !== "" && (
        <Button
          type="button"
          size="icon-sm"
          variant="secondary"
          aria-label="Queue this instruction"
          title="Queue — sends when the running turn finishes"
          onClick={onSend}
          className="shrink-0 rounded-full"
        >
          <Icon name="arrow-up" size={14} />
        </Button>
      )}
      {busy ? (
        <Button
          type="button"
          size="icon-sm"
          variant="outline"
          aria-label="Stop the answer"
          title="Stop"
          onClick={onStop}
          className="shrink-0 rounded-full"
        >
          <Icon name="stop" size={13} />
        </Button>
      ) : (
        <Button
          type="button"
          size={variant === "inline" ? "icon-xs" : "icon-sm"}
          variant="default"
          aria-label="Send"
          title="Send"
          onClick={onSend}
          disabled={value.trim() === ""}
          className="shrink-0 rounded-full"
        >
          <Icon name="arrow-up" size={variant === "inline" ? 13 : 15} />
        </Button>
      )}
    </div>
  )

  // Attachments sit ABOVE the row: they are what the question is about, and
  // reading them after the question would be reading the answer's evidence
  // out of order.
  if (attachments.length === 0) return row
  return (
    <div className="flex w-full flex-col gap-2">
      <MessageAttachments
        compact
        attachments={attachments}
        onRemove={onRemoveAttachment}
        className={variant === "panel" ? "pt-2" : undefined}
      />
      {row}
    </div>
  )
}

"use client"

import * as React from "react"

import { AnimatePresence, motion } from "framer-motion"

import { Button } from "@/components/ui/button"
import { Icon, type IconName } from "@/components/ui/icon"
import { Input } from "@/components/ui/input"
import { cn } from "@/lib/utils"

import { useMotionTransition } from "./ambient-runtime"

import { Composer } from "./composer"
import { StageSkeleton, StagedItem } from "./staging"
import { StreamingText } from "./streaming-text"
import { useElapsedSeconds, useStagedReveal } from "./use-staged-reveal"

import {
  FEEDBACK_REASONS,
  REASONING_EFFORTS,
  type ReasoningEffortLevel,
} from "./kit-vocabulary"

/**
 * How long the thinking state holds at minimum. Work that appears to finish
 * instantly reads as a lookup; this is a real wait, so the counter measuring
 * it stays a measurement rather than a decoration.
 */
export const THINKING_FLOOR_MS = 15_000

/**
 * THE MESSAGE KIT — the objects a conversation is made of once an answer
 * exists: what you can do to it, what it offers next, what it costs, and
 * how it fails.
 *
 * Every one of these is composed from the product vocabulary (Button, Input,
 * Icon) and the system's tokens. None of them defines a color, a blur, or a
 * duration of its own: status comes from --positive / --destructive, timing
 * from the motion roles.
 *
 * A shared rule runs through the whole file: THE ASSISTANT'S OBJECTS ARE
 * QUIET UNTIL THEY MATTER. Actions stay ghost-weight, failures state the
 * fact and offer the one useful move, and nothing animates that the user
 * did not cause.
 */

/* ------------------------------ actions ------------------------------- */

export type MessageRating = "up" | "down" | null

/**
 * MESSAGE ACTIONS — copy, rate, regenerate: the small row under an answer.
 *
 * Each action confirms ITSELF rather than raising a toast. Copy becomes a
 * check for a beat, a rating stays lit, and regenerate hands off to whoever
 * owns the answer. A toast for a copy is a notification about something the
 * user is already looking at.
 */
export function MessageActions({
  onCopy,
  rating = null,
  onRate,
  onRegenerate,
  onMore,
  text,
  className,
}: {
  /** Called after the text is on the clipboard; the check is handled here. */
  onCopy?: () => void
  rating?: MessageRating
  onRate?: (rating: MessageRating) => void
  onRegenerate?: () => void
  onMore?: () => void
  /** The text to copy. Omit to handle copying yourself via onCopy. */
  text?: string
  className?: string
}) {
  const [copied, setCopied] = React.useState(false)
  React.useEffect(() => {
    if (!copied) return
    const t = window.setTimeout(() => setCopied(false), 1400)
    return () => window.clearTimeout(t)
  }, [copied])

  const copy = async () => {
    if (text) {
      try {
        await navigator.clipboard.writeText(text)
      } catch {
        // clipboard can be denied; the check would be a lie, so bail quietly
        onCopy?.()
        return
      }
    }
    setCopied(true)
    onCopy?.()
  }

  const act = (name: IconName, label: string, on?: () => void, lit?: boolean) => (
    <Button
      size="icon-sm"
      variant="ghost"
      aria-label={label}
      title={label}
      aria-pressed={lit}
      onClick={on}
      className={cn(
        "text-muted-foreground hover:text-foreground",
        lit && "text-foreground"
      )}
    >
      <Icon name={name} size={13} />
    </Button>
  )

  return (
    <div className={cn("flex items-center gap-0.5", className)}>
      <Button
        size="icon-sm"
        variant="ghost"
        aria-label={copied ? "Copied" : "Copy"}
        title={copied ? "Copied" : "Copy"}
        onClick={copy}
        className={cn(
          "text-muted-foreground hover:text-foreground",
          copied && "text-(--positive)"
        )}
      >
        <Icon name={copied ? "check" : "copy"} size={13} />
      </Button>
      {act("thumbs-up", "Good answer", () => onRate?.(rating === "up" ? null : "up"), rating === "up")}
      {act("thumbs-down", "Bad answer", () => onRate?.(rating === "down" ? null : "down"), rating === "down")}
      {onRegenerate && act("replay", "Regenerate", onRegenerate)}
      {onMore && act("more", "More actions", onMore)}
    </div>
  )
}

/* --------------------------- follow-up prompts -------------------------- */

/**
 * FOLLOW-UP SUGGESTIONS — the next turns the assistant thinks are worth
 * taking, offered as prompts rather than performed.
 *
 * A titled group of rows, and deliberately only that. A pill row was the
 * obvious second shape and it was wrong: a real follow-up is a sentence, so it
 * wraps to two lines and needs a target the width of the surface. Squeezing it
 * into a pill produced something that could neither be read at a glance nor
 * scanned as a list.
 *
 * They stagger in because they arrive after the answer settles — a group that
 * appears all at once reads as chrome that was always there.
 */
export function FollowUpSuggestions({
  suggestions,
  onPick,
  label = "Ask more",
  className,
}: {
  suggestions: string[]
  onPick?: (suggestion: string) => void
  /** The group's heading; pass null to drop it. */
  label?: string | null
  className?: string
}) {
  const transition = useMotionTransition("control")
  if (suggestions.length === 0) return null

  return (
    <div
      className={cn(
        "border-border bg-card mt-3 overflow-hidden rounded-xl border",
        className
      )}
    >
      {label && (
        <div className="flex items-center gap-2 px-3 pt-2.5 pb-2">
          <span className="text-muted-foreground">
            <Icon name="sparkles" size={13} />
          </span>
          <span className="text-sm font-medium">{label}</span>
        </div>
      )}
      <div className={cn("divide-border divide-y", label && "border-border border-t")}>
        {suggestions.map((s, i) => (
          <motion.button
            key={s}
            type="button"
            onClick={() => onPick?.(s)}
            initial={{ opacity: 0, y: 4 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ ...transition, delay: i * 0.05 }}
            className="group/row hover:bg-(--wash) flex w-full items-start gap-3 px-3 py-2.5 text-start transition-colors"
          >
            {/* the question wraps — it is a sentence, not a label */}
            <span className="min-w-0 flex-1 text-sm leading-relaxed">
              {s}
            </span>
            <span className="bg-muted text-muted-foreground group-hover/row:text-foreground mt-0.5 flex size-6 shrink-0 items-center justify-center rounded-md transition-colors">
              <Icon name="arrow-up-right" size={12} />
            </span>
          </motion.button>
        ))}
      </div>
    </div>
  )
}

/* ------------------------------ failure -------------------------------- */

/**
 * ERROR STATE — a run that stopped, stated in place.
 *
 * A failed answer is not a system-level event: it belongs in the transcript
 * where the answer would have been, not in a modal over the user's work. It
 * says what happened, and offers the single move that helps.
 */
export function ErrorState({
  title = "Generation stopped",
  detail,
  onRetry,
  retryLabel = "Retry",
  className,
}: {
  title?: string
  detail?: string
  onRetry?: () => void
  retryLabel?: string
  className?: string
}) {
  return (
    <div
      role="alert"
      className={cn(
        "bg-(--destructive-wash) text-destructive flex items-start gap-2.5 rounded-xl px-3 py-2.5",
        className
      )}
    >
      <span className="mt-0.5 shrink-0">
        <Icon name="alert" size={15} />
      </span>
      <div className="min-w-0 flex-1">
        <div className="text-sm font-medium">{title}</div>
        {detail && <p className="mt-0.5 text-sm opacity-80">{detail}</p>}
      </div>
      {onRetry && (
        <Button
          size="sm"
          variant="ghost"
          onClick={onRetry}
          className="text-destructive hover:text-destructive shrink-0 hover:bg-(--destructive-wash)"
        >
          <Icon name="replay" size={13} />
          {retryLabel}
        </Button>
      )}
    </div>
  )
}

/* ------------------------------- queue --------------------------------- */

export interface QueuedTurn {
  id: string
  text: string
}

/**
 * MESSAGE QUEUE — turns typed while a run was in flight.
 *
 * The alternative designs both lose something: blocking the input makes the
 * user hold a thought, and interrupting on every send throws away work in
 * progress. A queue keeps both — and stays EDITABLE, because a queued turn is
 * a plan, not a commitment: cancel one the running answer already covered, or
 * send one NOW and let the running turn go back in the queue behind it.
 */
export function MessageQueue({
  running,
  queued,
  onInterrupt,
  onCancel,
  className,
}: {
  /** The turn currently being answered. */
  running?: string
  queued: QueuedTurn[]
  /**
   * Send this turn NOW — which necessarily interrupts the running one and
   * puts it back at the head of the queue. It is not a reorder: a queue whose
   * items can be shuffled while one of them is mid-answer implies the running
   * turn can be overtaken quietly, and it cannot.
   */
  onInterrupt?: (id: string) => void
  onCancel?: (id: string) => void
  className?: string
}) {
  const transition = useMotionTransition("control")
  if (!running && queued.length === 0) return null
  return (
    <div className={cn("flex flex-col gap-1.5", className)}>
      {running && (
        <div className="border-border bg-card flex items-center gap-2.5 rounded-xl border px-3 py-2">
          <span className="bg-primary size-2 shrink-0 animate-pulse rounded-full" />
          <span className="min-w-0 flex-1 truncate text-sm">{running}</span>
          {/* the state says it is working, so it wears the working treatment */}
          <span className="ambient-shimmer shrink-0 font-mono text-xs">
            running
          </span>
        </div>
      )}
      {queued.length > 0 && (
        <>
          <div className="text-muted-foreground flex items-baseline justify-between px-1 text-xs">
            <span>{queued.length} queued</span>
            <span className="font-mono">sends when this finishes</span>
          </div>
          <AnimatePresence initial={false}>
            {queued.map((q, i) => (
              <motion.div
                key={q.id}
                layout
                initial={{ opacity: 0, y: -4 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0, height: 0 }}
                transition={transition}
                className="bg-muted flex items-center gap-2.5 rounded-xl px-3 py-2"
              >
                <span className="text-muted-foreground shrink-0 font-mono text-xs">
                  {i + 1}
                </span>
                <span className="text-muted-foreground min-w-0 flex-1 truncate text-sm">
                  {q.text}
                </span>
                {onInterrupt && running && (
                  <Button
                    size="icon-sm"
                    variant="ghost"
                    aria-label={`Send "${q.text}" now, interrupting the running turn`}
                    title="Send now — interrupts the running turn"
                    onClick={() => onInterrupt(q.id)}
                    className="text-muted-foreground hover:text-foreground shrink-0"
                  >
                    <Icon name="arrow-up" size={13} />
                  </Button>
                )}
                {onCancel && (
                  <Button
                    size="icon-sm"
                    variant="ghost"
                    aria-label={`Remove "${q.text}" from the queue`}
                    onClick={() => onCancel(q.id)}
                    className="text-muted-foreground hover:text-foreground shrink-0"
                  >
                    <Icon name="close" size={13} />
                  </Button>
                )}
              </motion.div>
            ))}
          </AnimatePresence>
        </>
      )}
    </div>
  )
}

/* ----------------------------- reasoning ------------------------------- */

export interface ReasoningStep {
  title: string
  detail?: string
}

/**
 * REASONING PANEL — the trace, collapsed by default once it is over.
 *
 * Reasoning is interesting WHILE it happens and reference material after, so
 * the panel opens itself during the run and settles to a one-line summary
 * ("Thought for 5s") when it finishes. The user can always reopen it; it
 * just stops competing with the answer.
 */
export function ReasoningPanel({
  steps,
  seconds,
  running = false,
  defaultOpen,
  staged = true,
  className,
}: {
  steps: ReasoningStep[]
  /** How long the thinking took; shown in the settled summary. */
  seconds?: number
  running?: boolean
  defaultOpen?: boolean
  /**
   * Stage the arrival: shimmer, hold, then one step at a time. False renders
   * settled — an older trace re-rendered must never re-think itself.
   */
  staged?: boolean
  className?: string
}) {
  const [open, setOpen] = React.useState(defaultOpen ?? running)
  const transition = useMotionTransition("surface")
  // the trace arrives the way it was produced: a beat of nothing, then a
  // step, then the next
  const { shown, pending, working: counting } = useStagedReveal(steps.length, {
    // THINKING TAKES TIME. The steps land at their own pace, but the panel
    // holds the thinking state to a floor — an answer that appears to think
    // for two seconds and then knows everything is not what the work looked
    // like. The floor is a real wait, so the counter still measures it.
    minDuration: THINKING_FLOOR_MS,
    enabled: staged,
    // long enough to be a real wait, and paced so a step can be READ before
    // the next one lands rather than three arriving on top of each other
    delay: 2600,
    interval: 1500,
  })
  const working = staged && (pending || shown < steps.length)
  const elapsed = useElapsedSeconds(counting)
  // the settled summary quotes the time it ACTUALLY took, not a prop
  const took = staged ? Math.max(1, elapsed) : seconds
  // A run that starts opens the trace; finishing collapses it back — adjusted
  // DURING render on the transition, not from an effect, so the panel never
  // paints in the stale state first. (react.dev: adjusting state when a prop
  // changes.) The user's own toggle still wins until running flips again.
  const [wasRunning, setWasRunning] = React.useState(running)
  if (running !== wasRunning) {
    setWasRunning(running)
    if (defaultOpen === undefined) setOpen(running)
  }

  return (
    <div className={cn("flex flex-col", className)}>
      <button
        type="button"
        onClick={() => setOpen((v) => !v)}
        aria-expanded={open}
        className="text-muted-foreground hover:text-foreground flex items-center gap-1.5 self-start text-sm transition-colors"
      >
        <span className={cn(working && "ambient-shimmer")}>
          {running || working
            ? `Thinking… ${elapsed}s`
            : took !== undefined
              ? `Thought for ${took}s`
              : "Reasoning"}
        </span>
        <Icon name={open ? "chevron-down" : "chevron-right"} size={13} />
      </button>
      <AnimatePresence initial={false}>
        {open && (
          <motion.ol
            initial={{ opacity: 0, height: 0 }}
            animate={{ opacity: 1, height: "auto" }}
            exit={{ opacity: 0, height: 0 }}
            transition={transition}
            className="overflow-hidden"
          >
            {pending && <StageSkeleton rows={Math.min(2, steps.length)} />}
            {steps.slice(0, shown).map((s, i) => (
              <li key={s.title}>
                <StagedItem index={i} className="flex gap-2.5 pt-3">
                  {/* the timeline: a mark per step, not a connector — the
                      steps are ordered, not causally chained */}
                  <span
                    aria-hidden
                    className="bg-muted-foreground/40 mt-1.5 size-1.5 shrink-0 rounded-full"
                  />
                  <div className="min-w-0">
                    <div className="text-sm font-medium">{s.title}</div>
                    {s.detail && (
                      // the detail is written, not revealed — the same
                      // component the answer itself streams through
                      <StreamingText
                        text={s.detail}
                        live={staged}
                        className="text-muted-foreground mt-0.5 block text-sm"
                      />
                    )}
                  </div>
                </StagedItem>
              </li>
            ))}
          </motion.ol>
        )}
      </AnimatePresence>
    </div>
  )
}


/**
 * REASONING EFFORT — how hard to think, and what that budget actually cost.
 *
 * COLLAPSED BY DEFAULT, behind a ghost trigger that states the current level.
 * This is a setting, not a status: it earns a permanent strip of the composer
 * only if the user is changing it constantly, and they are not. The trigger
 * carries the one fact worth glancing at, and opening it reveals the choice
 * and the spend together.
 *
 * The control and the meter belong together: an effort setting with no spend
 * reading is a preference with invisible consequences. Showing both is what
 * lets someone learn that "high" is worth it here and not there.
 */
export function ReasoningEffort({
  level,
  onChange,
  spent,
  budget,
  label = "Thinking",
  defaultOpen = false,
  className,
}: {
  level: ReasoningEffortLevel
  onChange?: (level: ReasoningEffortLevel) => void
  /** Tokens spent against the budget; omit both to hide the meter. */
  spent?: number
  budget?: number
  label?: string
  /** Start expanded — for a settings surface, where it IS the content. */
  defaultOpen?: boolean
  className?: string
}) {
  const [open, setOpen] = React.useState(defaultOpen)
  const transition = useMotionTransition("surface")
  const ratio =
    spent !== undefined && budget ? Math.min(1, spent / budget) : null

  return (
    <div className={cn("flex flex-col gap-1.5", className)}>
      <Button
        size="sm"
        variant="ghost"
        aria-expanded={open}
        onClick={() => setOpen((v) => !v)}
        className="text-muted-foreground hover:text-foreground -ms-2 self-start font-normal"
      >
        <Icon name="sparkles" size={12} />
        {label}
        <span className="text-foreground capitalize">{level}</span>
        <Icon name={open ? "chevron-down" : "chevron-right"} size={12} />
      </Button>

      <AnimatePresence initial={false}>
        {open && (
          <motion.div
            initial={{ opacity: 0, height: 0 }}
            animate={{ opacity: 1, height: "auto" }}
            exit={{ opacity: 0, height: 0 }}
            transition={transition}
            className="overflow-hidden"
          >
            <div className="flex flex-col gap-1.5 pt-1">
              {ratio !== null && (
                <div className="flex items-baseline justify-between gap-4">
                  <span className="text-muted-foreground text-xs">
                    spent
                  </span>
                  <span className="text-muted-foreground font-mono text-xs tabular-nums">
                    {spent!.toLocaleString()} / {budget!.toLocaleString()}
                  </span>
                </div>
              )}
              <div
                role="radiogroup"
                aria-label={label}
                className="bg-muted flex items-center gap-0.5 rounded-full p-0.5"
              >
                {REASONING_EFFORTS.map((e) => (
                  <button
                    key={e}
                    type="button"
                    role="radio"
                    aria-checked={e === level}
                    onClick={() => onChange?.(e)}
                    className={cn(
                      "flex-1 rounded-full px-3 py-1 text-sm capitalize transition-colors",
                      e === level
                        ? "bg-card text-foreground shadow-xs"
                        : "text-muted-foreground hover:text-foreground"
                    )}
                  >
                    {e}
                  </button>
                ))}
              </div>
              {ratio !== null && (
                <div className="bg-muted h-1 overflow-hidden rounded-full">
                  <div
                    className="bg-primary h-full rounded-full transition-[width] duration-(--motion-surface)"
                    style={{ width: `${ratio * 100}%` }}
                  />
                </div>
              )}
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  )
}

/* ---------------------------- attachments ------------------------------ */

export interface MessageAttachment {
  id: string
  name: string
  /** Human-readable size, e.g. "412 KB" — formatting is the caller's data. */
  size?: string
  /** Extra fact worth showing, e.g. "14 pages". */
  meta?: string
  kind?: "image" | "document" | "file" | "text"
  /** A thumbnail for images; falls back to the kind's icon. */
  thumbnail?: string
  onOpen?: () => void
}

const ATTACHMENT_ICON: Record<
  NonNullable<MessageAttachment["kind"]>,
  IconName
> = { image: "image", document: "document", file: "paperclip", text: "quote" }

/**
 * MESSAGE ATTACHMENTS — what was attached, before or after sending.
 *
 * One component for both, because they are the same object at two moments,
 * and REMOVABILITY is the only honest difference: pass `onRemove` while the
 * attachment is still staged in the composer, omit it once the message is
 * sent and the attachment is a record. Two components would have drifted
 * into two ideas of what an attachment looks like.
 *
 * An image can be opened; everything else states what it is and how big —
 * enough to know whether it is the thing you meant. Pasted text is a `text`
 * attachment: it is quoted material, not a file, and it says so.
 */
export function MessageAttachments({
  attachments,
  onRemove,
  compact = false,
  className,
}: {
  attachments: MessageAttachment[]
  /** Present while the attachment can still be taken back — see above. */
  onRemove?: (id: string) => void
  /**
   * The composer's density: chips in one scrolling row rather than stacked
   * cards. Staged attachments sit BESIDE context chips and mean the same
   * thing — here is what the question is about — so they read as the same
   * kind of object. Stacked, four of them pushed the input off the surface,
   * which is the wrong trade for material you are only referring to.
   */
  compact?: boolean
  className?: string
}) {
  if (attachments.length === 0) return null

  if (compact) {
    return (
      <CompactAttachments
        attachments={attachments}
        onRemove={onRemove}
        className={className}
      />
    )
  }

  return (
    <div className={cn("flex flex-col gap-1.5", className)}>
      {attachments.map((a) => {
        const kind = a.kind ?? "file"
        // a removable row already contains a button, so it must not BE one:
        // while staged, removing wins over opening
        const openable = Boolean(a.onOpen) && !onRemove
        const Row = openable ? "button" : "div"
        return (
          <Row
            key={a.id}
            {...(openable
              ? { type: "button" as const, onClick: a.onOpen }
              : {})}
            className={cn(
              "flex w-full items-center gap-2.5 rounded-xl px-2 py-2 text-start",
              openable
                ? "border-border bg-card hover:bg-muted border transition-colors"
                : "bg-muted"
            )}
          >
            {a.thumbnail ? (
              <img
                src={a.thumbnail}
                alt=""
                className="size-9 shrink-0 rounded-lg object-cover"
              />
            ) : (
              <span
                className={cn(
                  "text-muted-foreground flex size-9 shrink-0 items-center justify-center rounded-lg",
                  openable ? "bg-muted" : "bg-card"
                )}
              >
                <Icon name={ATTACHMENT_ICON[kind]} size={16} />
              </span>
            )}
            <span className="min-w-0 flex-1">
              <span className="block truncate text-sm">{a.name}</span>
              {(a.size || a.meta) && (
                <span className="text-muted-foreground block font-mono text-xs">
                  {[a.size, a.meta].filter(Boolean).join(" · ")}
                </span>
              )}
            </span>
            {openable && !onRemove && (
              <span className="text-muted-foreground shrink-0">
                <Icon name={ATTACHMENT_ICON[kind]} size={14} />
              </span>
            )}
            {onRemove && (
              <Button
                type="button"
                size="icon-xs"
                variant="ghost"
                aria-label={`Remove ${a.name}`}
                title="Remove"
                onClick={(e) => {
                  e.stopPropagation()
                  onRemove(a.id)
                }}
                className="text-muted-foreground hover:text-foreground shrink-0"
              >
                <Icon name="close" size={12} />
              </Button>
            )}
          </Row>
        )
      })}
    </div>
  )
}

/**
 * CHIP SLIDER — one horizontal run of chips, with paging arrows.
 *
 * A row that scrolls and says nothing about it is a row most people read as
 * truncated: the arrows are the only thing that distinguishes "there is more"
 * from "that is all". They appear only when the content actually overflows,
 * so a single chip carries no chrome.
 *
 * It is a SLIDER, not a stack of sliders. Everything the question is about —
 * the page's own chip, attached context, pasted text, files — rides in this
 * one run. Two stacked rows read as two different kinds of thing and cost
 * twice the height above an input that is already the smallest part of the
 * surface.
 */
export function ChipSlider({
  children,
  /** Anything that can change the content width, so paging re-measures. */
  deps,
  className,
}: {
  children: React.ReactNode
  deps?: number
  className?: string
}) {
  const ref = React.useRef<HTMLDivElement | null>(null)
  const [edges, setEdges] = React.useState({ left: false, right: false })

  const measure = React.useCallback(() => {
    const el = ref.current
    if (!el) return
    const max = el.scrollWidth - el.clientWidth
    setEdges({ left: el.scrollLeft > 4, right: el.scrollLeft < max - 4 })
  }, [])

  React.useEffect(() => {
    const el = ref.current
    if (!el) return
    // measured from the observer/scroll callbacks, never synchronously in the
    // effect body — the first paint has no layout to read yet anyway
    const ro = new ResizeObserver(measure)
    ro.observe(el)
    el.addEventListener("scroll", measure, { passive: true })
    return () => {
      ro.disconnect()
      el.removeEventListener("scroll", measure)
    }
  }, [measure, deps])

  const page = (dir: -1 | 1) => {
    const el = ref.current
    if (!el) return
    el.scrollBy({
      left: dir * Math.max(160, el.clientWidth * 0.8),
      behavior: "smooth",
    })
  }

  const arrow = (dir: -1 | 1, shown: boolean) => (
    <Button
      type="button"
      size="icon-xs"
      variant="ghost"
      aria-label={dir === -1 ? "Scroll back" : "Scroll forward"}
      disabled={!shown}
      onClick={() => page(dir)}
      className={cn(
        "text-muted-foreground hover:text-foreground shrink-0 rounded-md transition-opacity",
        shown ? "opacity-100" : "pointer-events-none opacity-0"
      )}
    >
      <Icon name={dir === -1 ? "chevron-left" : "chevron-right"} size={13} />
    </Button>
  )

  const overflowing = edges.left || edges.right

  return (
    <div className={cn("flex items-center gap-1", className)}>
      {overflowing && arrow(-1, edges.left)}
      <div
        ref={ref}
        className="no-scrollbar flex min-w-0 flex-1 items-center gap-1.5 overflow-x-auto"
      >
        {children}
      </div>
      {overflowing && arrow(1, edges.right)}
    </div>
  )
}

/**
 * ONE STAGED ATTACHMENT, as a chip. Exported because the ambient layer's
 * context row renders these beside its own chips in the same slider — the
 * alternative was two places drawing an attachment, which is how two
 * drawings of one thing drift apart.
 */
export function AttachmentChip({
  attachment: a,
  onRemove,
}: {
  attachment: MessageAttachment
  onRemove?: (id: string) => void
}) {
  return (
    <span
      title={`${a.name}${a.meta ? ` · ${a.meta}` : ""}`}
      className="border-border inline-flex max-w-full shrink-0 items-center gap-2 rounded-lg border bg-(--wash) py-1 ps-1.5 pe-1 text-xs font-medium"
    >
      <span className="text-muted-foreground bg-card flex size-5 shrink-0 items-center justify-center rounded-[5px]">
        <Icon name={ATTACHMENT_ICON[a.kind ?? "file"]} size={12} />
      </span>
      <span className="max-w-44 min-w-0 truncate">{a.name}</span>
      {onRemove && (
        <Button
          type="button"
          size="icon-xs"
          variant="ghost"
          aria-label={`Remove ${a.name}`}
          title="Remove"
          onClick={() => onRemove(a.id)}
          className="text-muted-foreground hover:text-foreground size-[22px] shrink-0 rounded-md bg-accent"
        >
          <Icon name="close" size={11} />
        </Button>
      )}
    </span>
  )
}

/**
 * The compact row: attachments alone in a slider, for a composer with NO
 * context row above it. Where there is one, the context row owns the slider
 * and these chips ride inside it — one row, one owner.
 */
function CompactAttachments({
  attachments,
  onRemove,
  className,
}: {
  attachments: MessageAttachment[]
  onRemove?: (id: string) => void
  className?: string
}) {
  return (
    <ChipSlider deps={attachments.length} className={className}>
      {attachments.map((a) => (
        <AttachmentChip key={a.id} attachment={a} onRemove={onRemove} />
      ))}
    </ChipSlider>
  )
}


/* ----------------------------- quote reply ----------------------------- */

export type QuoteAction =
  | "explain"
  | "improve"
  | "shorten"
  | "tone"
  | "grammar"
  | "prompt"

type QuoteMode = "idle" | "thinking" | "streaming" | "result"

const PRIMARY_ACTIONS: { id: QuoteAction; label: string; icon: IconName }[] = [
  { id: "explain", label: "Explain", icon: "sparkles" },
  { id: "improve", label: "Improve", icon: "edit" },
]
const MORE_ACTIONS: { id: QuoteAction; label: string; icon: IconName }[] = [
  { id: "shorten", label: "Shorten", icon: "scissors" },
  { id: "tone", label: "Tone", icon: "smile" },
  { id: "grammar", label: "Grammar", icon: "type" },
]
const BUSY_LABEL: Record<QuoteAction, string> = {
  explain: "Explaining",
  improve: "Improving",
  shorten: "Shortening",
  tone: "Changing tone",
  grammar: "Fixing grammar",
  prompt: "Editing",
}

/**
 * QUOTE REPLY — select a phrase and a contextual bar attaches beneath it.
 *
 * ANCHORED, ABSOLUTELY. The bar measures the selection (`getClientRects`) and
 * positions itself under the LAST line, centred on the full bounds — so a
 * selection that wraps still reads as one object with its bar. Re-measured on
 * selection change and resize, batched through requestAnimationFrame so
 * mid-layout positions never paint.
 *
 * A STATE MACHINE, not a toolbar: idle (prompt input + actions) → thinking
 * (spinner + shimmer with the real elapsed count) → streaming (the rewrite
 * arrives INTO the selection through StreamingText) → result (Keep / Discard /
 * Retry). Rewriting in place requires owning the prose, so the component takes
 * `text` and an optional `rewrite` seam; without one it only reports actions,
 * which is what a surface that cannot mutate its content should get.
 */
export function QuoteReply({
  text,
  children,
  rewrite,
  onAction,
  className,
}: {
  /** The prose, when the component owns it (enables rewrite-in-place). */
  text?: string
  /** Alternatively, arbitrary content — actions are report-only. */
  children?: React.ReactNode
  /** The model seam: produce the replacement for a selection. */
  rewrite?: (action: QuoteAction, selection: string, prompt?: string) => string
  onAction?: (action: QuoteAction, selection: string) => void
  className?: string
}) {
  const hostRef = React.useRef<HTMLDivElement | null>(null)
  const frameRef = React.useRef<number | null>(null)
  const [selection, setSelection] = React.useState("")
  const [range, setRange] = React.useState<[number, number] | null>(null)
  const [anchor, setAnchor] = React.useState<{ x: number; y: number } | null>(null)
  const [mode, setMode] = React.useState<QuoteMode>("idle")
  const [action, setAction] = React.useState<QuoteAction>("improve")
  const [prompt, setPrompt] = React.useState("")
  const [expanded, setExpanded] = React.useState(false)
  const [replacement, setReplacement] = React.useState("")
  const transition = useMotionTransition("control")
  const elapsed = useElapsedSeconds(mode === "thinking")

  /* attach beneath the final selected line, centred on the whole selection */
  const place = React.useCallback(() => {
    if (frameRef.current !== null) cancelAnimationFrame(frameRef.current)
    frameRef.current = requestAnimationFrame(() => {
      const host = hostRef.current
      const sel = window.getSelection()
      if (!host || !sel || sel.rangeCount === 0) return
      const rects = Array.from(sel.getRangeAt(0).getClientRects())
      const last = rects.at(-1)
      const bounds = sel.getRangeAt(0).getBoundingClientRect()
      if (!last || bounds.width === 0) return
      const hostBounds = host.getBoundingClientRect()
      setAnchor({
        x: Math.round(bounds.left - hostBounds.left + bounds.width / 2),
        y: Math.round(last.bottom - hostBounds.top + 8),
      })
    })
  }, [])

  React.useEffect(() => {
    const read = () => {
      // the bar owns the interaction once a run starts; the selection
      // collapsing (a click on the bar) must not dismiss mid-run
      if (mode !== "idle") return
      const sel = window.getSelection()
      const value = sel?.toString().trim() ?? ""
      const inside = sel?.anchorNode && hostRef.current?.contains(sel.anchorNode)
      if (value && inside) {
        setSelection(value)
        if (text && sel && sel.rangeCount > 0) {
          const i = text.indexOf(value)
          setRange(i >= 0 ? [i, i + value.length] : null)
        }
        place()
      } else {
        setSelection("")
        setAnchor(null)
        setPrompt("")
        setExpanded(false)
      }
    }
    document.addEventListener("selectionchange", read)
    window.addEventListener("resize", place)
    return () => {
      document.removeEventListener("selectionchange", read)
      window.removeEventListener("resize", place)
      if (frameRef.current !== null) cancelAnimationFrame(frameRef.current)
    }
  }, [mode, place, text])

  const canRewrite = Boolean(text && rewrite && range)
  const run = (a: QuoteAction, p?: string) => {
    setAction(a)
    setExpanded(false)
    onAction?.(a, selection)
    if (!canRewrite || a === "explain") {
      // explain reads, it does not edit — and without the rewrite seam
      // there is nothing to write into
      setSelection("")
      setAnchor(null)
      return
    }
    setReplacement(rewrite!(a, selection, p))
    setMode("thinking")
    window.setTimeout(() => setMode("streaming"), 1400)
  }
  const settle = (keep: boolean) => {
    if (keep && range) setApplied({ range, value: replacement })
    setMode("idle")
    setSelection("")
    setAnchor(null)
    setPrompt("")
  }
  const [applied, setApplied] = React.useState<{
    range: [number, number]
    value: string
  } | null>(null)

  /* the prose, with the selection swapped live while a rewrite streams */
  const renderText = () => {
    if (!text) return children
    const base = applied
      ? text.slice(0, applied.range[0]) + applied.value + text.slice(applied.range[1])
      : text
    if ((mode === "streaming" || mode === "result") && range && !applied) {
      return (
        <>
          {text.slice(0, range[0])}
          <span className="bg-(--wash) rounded-[3px] box-decoration-clone">
            {mode === "streaming" ? (
              <StreamingText
                text={replacement}
                live
                onSettled={() => setMode("result")}
                className="inline"
              />
            ) : (
              replacement
            )}
          </span>
          {text.slice(range[1])}
        </>
      )
    }
    return base
  }


  return (
    <div ref={hostRef} className={cn("relative", className)}>
      {text ? <p className="text-sm leading-relaxed">{renderText()}</p> : children}
      <AnimatePresence>
        {(anchor && (selection || mode !== "idle")) && (
          <motion.div
            key="bar"
            initial={{ opacity: 0, scale: 0.92, y: 4 }}
            animate={{ opacity: 1, scale: 1, y: 0 }}
            exit={{ opacity: 0, scale: 0.95, y: 4 }}
            transition={transition}
            className="absolute top-0 left-0 z-10"
            style={{
              transform: `translate(${anchor.x}px, ${anchor.y}px) translateX(-50%)`,
            }}
          >
            <div
              // pressing a control must not collapse the selection: the
              // collapse fires selectionchange, which would unmount this bar
              // before the click it was aimed at ever lands
              onPointerDown={(e) => e.preventDefault()}
              className="border-border bg-card flex h-9 w-fit max-w-[calc(100vw-3rem)] items-center gap-0.5 overflow-hidden rounded-full border p-1 shadow-lg"
            >
              {(mode === "thinking" || mode === "streaming") && (
                <span className="flex h-7 items-center gap-1.5 px-2.5 text-xs whitespace-nowrap">
                  <span className="border-muted-foreground/30 border-t-primary size-3 shrink-0 animate-spin rounded-full border-[1.5px]" />
                  {mode === "thinking" ? (
                    <span className="ambient-shimmer tabular-nums">
                      {BUSY_LABEL[action]}… {elapsed}s
                    </span>
                  ) : (
                    <span className="text-muted-foreground">
                      {BUSY_LABEL[action]}…
                    </span>
                  )}
                </span>
              )}

              {mode === "result" && (
                <>
                  <Button
                    size="sm"
                    onClick={() => settle(true)}
                    className="shrink-0 rounded-full"
                  >
                    <Icon name="check" size={12} />
                    Keep
                  </Button>
                  <Button
                    size="sm"
                    variant="ghost"
                    onClick={() => settle(false)}
                    className="shrink-0 rounded-full font-normal"
                  >
                    <Icon name="close" size={12} />
                    Discard
                  </Button>
                  <span className="bg-border mx-0.5 h-4 w-px shrink-0" />
                  <Button
                    size="icon-sm"
                    variant="ghost"
                    aria-label="Try again"
                    onClick={() => run(action, prompt || undefined)}
                    className="shrink-0 rounded-full"
                  >
                    <Icon name="replay" size={13} />
                  </Button>
                </>
              )}

              {mode === "idle" && (
                <>
                  <form
                    className="flex h-7 shrink-0 items-center"
                    onSubmit={(e) => {
                      e.preventDefault()
                      if (prompt.trim()) run("prompt", prompt.trim())
                    }}
                  >
                    <input
                      value={prompt}
                      onPointerDown={(e) => e.stopPropagation()}
                      onChange={(e) => setPrompt(e.target.value)}
                      aria-label="Describe edits"
                      placeholder="Describe edits"
                      className="placeholder:text-muted-foreground h-7 w-32 bg-transparent ps-2.5 pe-1 text-xs outline-none"
                    />
                  </form>
                  {prompt.trim() ? (
                    <Button
                      size="icon-sm"
                      aria-label="Send edit instruction"
                      onClick={() => run("prompt", prompt.trim())}
                      className="shrink-0 rounded-full"
                    >
                      <Icon name="arrow-up" size={13} />
                    </Button>
                  ) : (
                    <>
                      <span className="bg-border mx-0.5 h-4 w-px shrink-0" />
                      {PRIMARY_ACTIONS.map((a) => (
                        <Button
                          key={a.id}
                          size="sm"
                          variant="ghost"
                          onClick={() => run(a.id)}
                          className="shrink-0 rounded-full font-normal"
                        >
                          <Icon name={a.icon} size={12} />
                          {a.label}
                        </Button>
                      ))}
                      {/* the long tail unfolds inside the pill, so the bar
                          grows instead of becoming a menu */}
                      <motion.div
                        animate={{
                          width: expanded ? "auto" : 0,
                          opacity: expanded ? 1 : 0,
                        }}
                        transition={transition}
                        className="flex items-center gap-0.5 overflow-hidden"
                      >
                        {MORE_ACTIONS.map((a) => (
                          <Button
                            key={a.id}
                            size="sm"
                            variant="ghost"
                            onClick={() => run(a.id)}
                            className="shrink-0 rounded-full font-normal"
                          >
                            <Icon name={a.icon} size={12} />
                            {a.label}
                          </Button>
                        ))}
                      </motion.div>
                      <span className="bg-border mx-0.5 h-4 w-px shrink-0" />
                      <Button
                        size="icon-sm"
                        variant="ghost"
                        aria-label={expanded ? "Show fewer actions" : "Show more actions"}
                        aria-expanded={expanded}
                        onClick={() => setExpanded((v) => !v)}
                        className="shrink-0 rounded-full"
                      >
                        <motion.span
                          animate={{ rotate: expanded ? 180 : 0 }}
                          transition={transition}
                          className="flex"
                        >
                          <Icon name="chevron-right" size={13} />
                        </motion.span>
                      </Button>
                    </>
                  )}
                </>
              )}
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  )
}

/* --------------------------- feedback dialog --------------------------- */


/**
 * FEEDBACK DIALOG — the thumbs-down that asks why.
 *
 * A bare rating is a number nobody can act on. Asking for a reason at the
 * moment of the reaction is the only time the user actually knows it. Every
 * field is optional, and the reasons are preset because free text is a tax
 * on the person doing you a favor.
 *
 * Not a modal: it opens under the answer it is about. (The system has no
 * Dialog — see the /ds registry's known gaps — and this is a case where
 * that constraint produced the better interaction.)
 */
export function FeedbackDialog({
  onSubmit,
  onDismiss,
  className,
}: {
  onSubmit?: (feedback: { reasons: string[]; note: string }) => void
  onDismiss?: () => void
  className?: string
}) {
  const [reasons, setReasons] = React.useState<string[]>([])
  const [note, setNote] = React.useState("")
  const toggle = (r: string) =>
    setReasons((rs) => (rs.includes(r) ? rs.filter((x) => x !== r) : [...rs, r]))

  return (
    <div
      role="group"
      aria-label="What went wrong?"
      className={cn(
        "border-border bg-card flex w-full max-w-sm flex-col gap-3 rounded-xl border p-3 shadow-xs",
        className
      )}
    >
      <div className="flex items-center gap-2">
        <span className="bg-muted text-muted-foreground flex size-7 shrink-0 items-center justify-center rounded-lg">
          <Icon name="thumbs-down" size={14} />
        </span>
        <span className="flex-1 text-sm font-medium">What went wrong?</span>
        <span className="text-muted-foreground font-mono text-xs">
          optional
        </span>
      </div>
      <div className="flex flex-wrap gap-1.5">
        {FEEDBACK_REASONS.map((r) => (
          <Button
            key={r}
            size="sm"
            variant={reasons.includes(r) ? "secondary" : "ghost"}
            aria-pressed={reasons.includes(r)}
            onClick={() => toggle(r)}
            className={cn(
              "rounded-full font-normal",
              !reasons.includes(r) && "bg-muted"
            )}
          >
            {r}
          </Button>
        ))}
      </div>
      {/* the system has no Textarea; a single line is the documented
          substitute, and it also discourages an essay nobody will read */}
      <Input
        value={note}
        onChange={(e) => setNote(e.target.value)}
        placeholder="Anything else?"
        aria-label="Anything else?"
      />
      <div className="flex items-center justify-end gap-1.5">
        {onDismiss && (
          <Button size="sm" variant="ghost" onClick={onDismiss}>
            Cancel
          </Button>
        )}
        <Button size="sm" onClick={() => onSubmit?.({ reasons, note })}>
          Send feedback
        </Button>
      </div>
    </div>
  )
}

/* ----------------------------- timestamps ------------------------------ */

/**
 * DAY DIVIDER — chronology in a long thread, marked only where it changes.
 *
 * A timestamp on every message is noise; a day boundary is the only moment
 * a reader actually needs orienting. Exact times live on hover (see
 * MessageTime), so precision is available without being ambient.
 */
export function DayDivider({
  label,
  className,
}: {
  label: string
  className?: string
}) {
  return (
    <div
      className={cn("flex items-center gap-3 py-1", className)}
      role="separator"
      aria-label={label}
    >
      <span className="bg-border h-px flex-1" />
      <span className="text-muted-foreground font-mono text-xs">
        {label}
      </span>
      <span className="bg-border h-px flex-1" />
    </div>
  )
}

/** The exact time for one message: present, but only on hover or focus. */
export function MessageTime({
  time,
  className,
}: {
  time: string
  className?: string
}) {
  return (
    <span
      className={cn(
        "text-muted-foreground pointer-events-none font-mono text-xs opacity-0 transition-opacity group-hover:opacity-100 group-focus-within:opacity-100",
        className
      )}
    >
      {time}
    </span>
  )
}

