/* ---------------------------- review comment ---------------------------- */

export type ReviewStatus = "comment" | "change-requested" | "resolved"

const REVIEW_STATUS: Record<ReviewStatus, { label: string; className: string }> = {
  comment: { label: "Comment", className: "bg-muted text-muted-foreground" },
  "change-requested": {
    label: "Change requested",
    className: "bg-(--destructive-wash) text-destructive",
  },
  resolved: {
    label: "Resolved",
    className: "bg-(--positive-wash) text-(--positive)",
  },
}

/**
 * REVIEW COMMENT — a human's note threaded into the code it is about, with
 * the assistant reachable from inside the thread.
 *
 * The anchoring is the whole point. A review comment in a side panel makes
 * the reader hold a line number in their head and scroll; threaded under the
 * line, the question and the code it questions are one object. That is also
 * what makes the reply seam honest: "resolve this" has an unambiguous
 * referent, so the assistant is answering about a specific line rather than
 * about a file.
 *
 * The status is stated, not implied by color alone — a red tint is not a
 * word, and "Change requested" is the difference between an opinion and a
 * blocker.
 */
export function ReviewComment({
  author,
  when,
  status = "comment",
  text,
  onReply,
  replyPlaceholder = "Leave a reply…",
  className,
}: {
  author: string
  when?: string
  status?: ReviewStatus
  text: string
  /** Omit and the thread is read-only — a record, with no reply affordance. */
  onReply?: (text: string) => void
  replyPlaceholder?: string
  className?: string
}) {
  const [reply, setReply] = React.useState("")
  const badge = REVIEW_STATUS[status]
  const send = () => {
    const t = reply.trim()
    if (!t) return
    onReply?.(t)
    setReply("")
  }
  return (
    <div
      className={cn(
        // the ambient glass: a thread the assistant can act on belongs to
        // the layer's material, not to the editor's chrome
        "ambient-glass border-(--glass-border) flex flex-col gap-2 rounded-xl border p-3",
        className
      )}
    >
      <div className="flex items-center gap-2">
        <span
          aria-hidden
          className="bg-muted text-muted-foreground flex size-5 shrink-0 items-center justify-center rounded-full text-[0.625rem] font-medium uppercase"
        >
          {author.trim().charAt(0)}
        </span>
        <span className="text-sm font-medium">{author}</span>
        {when && (
          <span className="text-muted-foreground font-mono text-xs">{when}</span>
        )}
        <span
          className={cn(
            "ms-1 rounded-md px-1.5 py-0.5 text-xs font-medium",
            badge.className
          )}
        >
          {badge.label}
        </span>
      </div>
      <p className="text-sm leading-relaxed">{text}</p>
      {/* THE ONE COMPOSER, inline variant. Replying here is not a comment
          box that happens to look similar — it is the same instrument, and
          what the user writes hands over to the ambient layer with this line
          already attached as context. */}
      {onReply && (
        <Composer
          variant="inline"
          value={reply}
          onChange={setReply}
          onSend={send}
          placeholder={replyPlaceholder}
        />
      )}
    </div>
  )
}

"use client"

import * as React from "react"
import {
  DEFAULT_STATE_SPEEDS,
  type OrbState,
} from "./kit-vocabulary"

import { Heatmap } from "@paper-design/shaders-react"
import { animate, useAnimationFrame, useMotionValue } from "framer-motion"

import { cn } from "@/lib/utils"

import { useAmbientAsset, useAmbientRuntime } from "./ambient-runtime"

/**
 * The orb character — the assistant's animated identity: the Paper Design
 * heatmap shader wrapped around a circle, so heat flows around the orb's
 * edge like thermal energy. (The one sanctioned shader surface, DESIGN.md
 * §5 — implemented via @paper-design/shaders-react.)
 *
 * Each state has its own MOVEMENT, not just speed — the heat itself
 * behaves differently:
 * - "still"     — calm, balanced glow breathing around the edge.
 * - "listening" — heat drawn INWARD (inner glow dominates, waves angled
 *                 in): the orb absorbing what it hears.
 * - "thinking"  — hot: fast flow, high contour, grain, heat radiating
 *                 both ways — the orb working.
 * - "answer"    — a one-shot outward bloom (outer glow surges and decays),
 *                 then a slow, settled glow: found it.
 *
 * Transitions are continuous — every parameter is a Framer Motion spring
 * (the sanctioned animation library, DESIGN.md §5) retargeted on state
 * change, so velocity carries through: a state change is a transition,
 * never a cut, and interrupting one mid-flight stays smooth. Per-state
 * speeds and the palette come from the Foundation orb config; palette is
 * accent-linked by default (a thermal ramp derived from the accent) or
 * custom colors used as the heat ramp (cold → hot).
 */




/** Per-state movement targets for the heat itself. */
const STATE_PARAMS: Record<
  OrbState,
  {
    speed: number
    contour: number
    innerGlow: number
    outerGlow: number
    noise: number
    angle: number
  }
> = {
  still: { speed: 0.5, contour: 0.5, innerGlow: 0.35, outerGlow: 0.3, noise: 0, angle: 0 },
  listening: { speed: 0.7, contour: 0.62, innerGlow: 0.8, outerGlow: 0.1, noise: 0, angle: 180 },
  thinking: { speed: 2.2, contour: 0.92, innerGlow: 0.5, outerGlow: 0.55, noise: 0, angle: 90 },
  answer: { speed: 0.45, contour: 0.68, innerGlow: 0.45, outerGlow: 0.42, noise: 0, angle: 0 },
}

/**
 * Where every heat surface WAKES from: hotter than any resting state, so
 * the first seconds after mount are visibly alive — the springs then
 * settle into the actual state. Without this, a page that loads into
 * `still` reads as a frozen image until the first state change.
 */
const WAKE_PARAMS = {
  speed: 2.4,
  contour: 0.9,
  innerGlow: 0.6,
  outerGlow: 0.6,
  noise: 0,
  angle: 120,
}

/** The shape the heat wraps: a filled circle with room for the outer
    glow. Served as a real file — the shader's loader rejects data URIs.
    The NAME only: the host's assetBase resolves it (useAmbientAsset), so a
    site under a subpath does not silently load nothing. */
const CIRCLE_IMAGE = "orb-circle.svg?v=2"

/**
 * Resolve any CSS color string to hex — including oklch(), which is what
 * Tailwind v4's palette variables actually contain. Canvas fillStyle
 * echoes oklch back verbatim, so rasterize a pixel and read it: the only
 * conversion that works for every color syntax the tokens might use.
 */
function resolveHex(css: string): string {
  const value = css.trim() || "#2563eb"
  if (/^#[0-9a-f]{6}$/i.test(value)) return value
  const canvas = document.createElement("canvas")
  canvas.width = canvas.height = 1
  const ctx = canvas.getContext("2d", { willReadFrequently: true })
  if (!ctx) return "#2563eb"
  ctx.fillStyle = value
  ctx.fillRect(0, 0, 1, 1)
  const [r, g, b] = ctx.getImageData(0, 0, 1, 1).data
  return rgbToHex(r!, g!, b!)
}

function hexToRgb(hex: string): [number, number, number] {
  const n = parseInt(hex.slice(1, 7), 16)
  return [(n >> 16) & 255, (n >> 8) & 255, n & 255]
}
function rgbToHex(r: number, g: number, b: number): string {
  const c = (v: number) =>
    Math.max(0, Math.min(255, Math.round(v))).toString(16).padStart(2, "0")
  return "#" + c(r) + c(g) + c(b)
}

/** Accent-linked thermal ramp: cold deep accent -> accent -> pale -> hot complement. */
function accentRamp(): string[] {
  const css = getComputedStyle(document.documentElement).getPropertyValue(
    "--ambient-accent"
  )
  const [r, g, b] = hexToRgb(resolveHex(css))
  return [
    // cold end transparent — the heat lives at the rim; the core is a
    // separate CSS layer under the canvas
    rgbToHex(r * 0.45, g * 0.45, b * 0.6) + "00",
    rgbToHex(r * 0.45, g * 0.45, b * 0.6) + "55",
    rgbToHex(r, g, b),
    rgbToHex(r * 0.35 + 166, g * 0.35 + 166, b * 0.35 + 166),
    rgbToHex(b, r, g),
    rgbToHex(255, Math.max(g, 120), 60),
  ]
}

/**
 * The orb at glyph scale — a pure-CSS stand-in for marks and avatars
 * (≤32px), where the shader's detail is invisible but its cost is not:
 * every OrbCharacter is a fresh WebGL context, a shader compile, and a
 * 60fps loop, which is exactly what made surfaces stutter on open. Same
 * anatomy (glass shell, accent core), zero runtime cost.
 */
export function OrbGlyph({
  size = 20,
  color,
  state,
  className,
}: {
  size?: number
  /** Core color; defaults to the ambient accent. */
  color?: string
  /** Ambient state — paces the glyph's breath (CSS, no shader). */
  state?: OrbState
  className?: string
}) {
  const core = color ?? "var(--ambient-accent)"
  return (
    <span
      aria-hidden
      data-orb-state={state ?? "still"}
      className={cn("relative inline-block shrink-0 rounded-full", className)}
      style={{
        width: size,
        height: size,
        backgroundColor: "var(--glass-core)",
        boxShadow: "inset 0 0 0 1px var(--glass-border)",
      }}
    >
      <span
        className="ambient-glyph-orbit absolute rounded-full"
        style={{ inset: "12%" }}
      />
      <span
        className="ambient-glyph-core absolute rounded-full"
        style={{
          inset: "20%",
          background: `radial-gradient(circle at 35% 30%, color-mix(in oklab, ${core} 55%, white), ${core} 58%, color-mix(in oklab, ${core} 62%, black))`,
          filter: "blur(0.5px)",
        }}
      />
    </span>
  )
}

/**
 * A LOST WebGL CONTEXT FREEZES A HEAT SURFACE ON ITS LAST FRAME — the
 * browser caps live contexts per page and evicts the oldest when a new
 * one is created, which is exactly the long-lived surfaces (the wordmark,
 * the page ground). The canvas announces the loss; remounting the shader
 * builds a fresh context, so the identity never quietly dies. Every heat
 * surface wears this listener.
 */
function useShaderEpoch(
  hostRef: React.RefObject<HTMLElement | null>,
  ready: boolean
) {
  const [epoch, setEpoch] = React.useState(0)
  React.useEffect(() => {
    if (!ready) return
    const canvas = hostRef.current?.querySelector("canvas")
    if (!canvas) return
    const onLost = (e: Event) => {
      e.preventDefault()
      setEpoch((n) => n + 1)
    }
    canvas.addEventListener("webglcontextlost", onLost)
    return () => canvas.removeEventListener("webglcontextlost", onLost)
  }, [hostRef, ready, epoch])
  return epoch
}

export interface OrbCharacterProps {
  state?: OrbState
  /** Diameter in px. */
  size?: number
  /** Global motion multiplier — 1 is the designed cadence. */
  speed?: number
  /** Custom heat ramp (cold -> hot, 1-4 CSS colors). Omit for accent-linked. */
  colors?: string[]
  /** Per-state cadence multipliers; merged over DEFAULT_STATE_SPEEDS. */
  speeds?: Partial<Record<OrbState, number>>
  className?: string
}

/**
 * The shared heat engine: spring-driven shader params + the palette, one
 * state machine for every heat surface (the orb character, the ambient
 * field). Springs carry velocity across retargets; the answer state runs
 * its one-shot outward bloom.
 */
function useHeatEngine({
  state,
  speed = 1,
  speeds,
  colors,
}: {
  state: OrbState
  speed?: number
  speeds?: Partial<Record<OrbState, number>>
  colors?: string[]
}) {
  const [params, setParams] = React.useState(() => ({ ...WAKE_PARAMS }))
  const [palette, setPalette] = React.useState<string[]>([])

  // Each shader parameter is a spring-driven motion value. Springs carry
  // velocity across retargets, so a state change mid-transition leans in
  // and settles out instead of restarting — the S-curve the character
  // needs, for free. Per-parameter spring characters: the flow speed
  // glides, the glows breathe, the wave direction swings deliberately.
  const mv = {
    speed: useMotionValue(WAKE_PARAMS.speed),
    contour: useMotionValue(WAKE_PARAMS.contour),
    innerGlow: useMotionValue(WAKE_PARAMS.innerGlow),
    outerGlow: useMotionValue(WAKE_PARAMS.outerGlow),
    angle: useMotionValue(WAKE_PARAMS.angle),
  }
  const mvRef = React.useRef(mv)
  // the frame loop reads the latest values, so the ref is refreshed after
  // commit rather than during render (React may render without committing)
  React.useEffect(() => {
    mvRef.current = mv
  })

  // per-state cadence config scales the heat's flow speed
  const speedFactor =
    ((speeds?.[state] ?? DEFAULT_STATE_SPEEDS[state]) /
      DEFAULT_STATE_SPEEDS[state]) *
    (speed ?? 1)

  React.useEffect(() => {
    const m = mvRef.current
    const target = STATE_PARAMS[state]
    const spring = (opts: { stiffness: number; damping: number; mass?: number }) =>
      ({ type: "spring", ...opts }) as const

    const controls = [
      animate(m.speed, target.speed * speedFactor, spring({ stiffness: 50, damping: 18, mass: 1.2 })),
      animate(m.innerGlow, target.innerGlow, spring({ stiffness: 110, damping: 20 })),
      animate(m.angle, target.angle, spring({ stiffness: 45, damping: 16, mass: 1.4 })),
    ]
    if (state === "answer") {
      // one-shot outward bloom: surge past the resting glow, then decay
      // into it — keyframes from the CURRENT value, so re-entry mid-flight
      // stays continuous
      controls.push(
        animate(
          m.outerGlow,
          [null as unknown as number, Math.min(1, target.outerGlow + 0.6), target.outerGlow],
          { duration: 1.6, times: [0, 0.2, 1], ease: ["easeOut", "easeOut"] }
        ),
        animate(
          m.contour,
          [null as unknown as number, Math.min(1, target.contour + 0.25), target.contour],
          { duration: 1.6, times: [0, 0.2, 1], ease: ["easeOut", "easeOut"] }
        )
      )
    } else {
      controls.push(
        animate(m.outerGlow, target.outerGlow, spring({ stiffness: 110, damping: 20 })),
        animate(m.contour, target.contour, spring({ stiffness: 130, damping: 22 }))
      )
    }
    return () => controls.forEach((c) => c.stop())
  }, [state, speedFactor])

  // Feed the springs into the shader once per frame; refresh the palette
  // (theme accent or custom ramp) at a slow cadence.
  const frameCount = React.useRef(0)
  const paletteKey = React.useRef("")
  const colorsRef = React.useRef(colors)
  React.useEffect(() => {
    colorsRef.current = colors
  })
  // Each shader param feeds React state, so an un-quantized read re-renders
  // this instance 60× a second — forever, since springs never land on an
  // exact value. Rounding lets the equality check succeed once a transition
  // settles (zero renders at rest) and sampling every third frame is
  // indistinguishable at these speeds.
  const q = (v: number, p = 100) => Math.round(v * p) / p
  useAnimationFrame(() => {
    const frame = frameCount.current++
    if (frame % 3 === 0) {
      const m = mvRef.current
      setParams((prev) => {
        const next = {
          speed: q(m.speed.get()),
          contour: q(m.contour.get()),
          innerGlow: q(m.innerGlow.get()),
          outerGlow: q(m.outerGlow.get()),
          noise: 0,
          angle: q(m.angle.get(), 10),
        }
        const same =
          next.speed === prev.speed &&
          next.contour === prev.contour &&
          next.innerGlow === prev.innerGlow &&
          next.outerGlow === prev.outerGlow &&
          next.angle === prev.angle
        return same ? prev : next
      })
    }
    if (frame % 30 === 0) {
      const custom = colorsRef.current
      const next =
        custom && custom.length > 0
          ? [resolveHex(custom[0]!) + "00", ...custom.map(resolveHex)]
          : accentRamp()
      const key = next.join()
      if (key !== paletteKey.current) {
        paletteKey.current = key
        setPalette(next)
      }
    }
  })

  return { params, palette }
}

export function OrbCharacter({
  state = "still",
  size = 96,
  speed = 1,
  colors,
  speeds,
  className,
}: OrbCharacterProps) {
  const { params, palette } = useHeatEngine({ state, speed, speeds, colors })
  const hostRef = React.useRef<HTMLDivElement>(null)
  const epoch = useShaderEpoch(hostRef, palette.length > 0)
  const circle = useAmbientAsset(CIRCLE_IMAGE)
  const coreColor =
    colors && colors.length > 0
      ? colors[Math.min(1, colors.length - 1)]!
      : "var(--ambient-accent)"

  return (
    <div
      ref={hostRef}
      aria-hidden
      className={cn("relative overflow-hidden rounded-full", className)}
      style={{
        width: size,
        height: size,
        // frosted glass: the page blurs through; tint and hairline derive
        // from theme tokens
        backdropFilter: "blur(var(--ambient-blur)) saturate(1.15)",
        WebkitBackdropFilter: "blur(var(--ambient-blur)) saturate(1.15)",
        backgroundColor: "var(--glass-core)",
        boxShadow: "inset 0 0 0 1px var(--glass-border)",
      }}
    >
      {/* the accent core — the middle wears the theme; the shell around it
          stays frosted glass, the rim heat renders above */}
      <div
        style={{
          position: "absolute",
          inset: "20%",
          borderRadius: "9999px",
          background: `radial-gradient(circle at 35% 30%, color-mix(in oklab, ${coreColor} 55%, white), ${coreColor} 58%, color-mix(in oklab, ${coreColor} 62%, black))`,
          filter: "blur(2px)",
        }}
      />
      {palette.length > 0 && (
        <Heatmap
          key={epoch}
          width={size}
          height={size}
          image={circle}
          colors={palette}
          colorBack="#00000000"
          contour={params.contour}
          angle={params.angle}
          noise={0}
          innerGlow={params.innerGlow}
          outerGlow={params.outerGlow}
          speed={params.speed}
          scale={1}
          fit="contain"
        />
      )}
    </div>
  )
}

/**
 * OrbHeat — the character's heat, unwrapped: the exact shader the orb
 * renders (same engine, same springs, same circle image, same palette),
 * with none of the character's glass shell. FOR SANCTIONED IDENTITY
 * SURFACES ONLY — the shader-surface rule applies to this export exactly
 * as it does to the character; a product surface wanting it is a
 * governance event. Width/height size the render; `image` picks the heat
 * shape (the character's circle by default, or a surface rect so the heat
 * hugs a band); the box shows whatever slice the host clips.
 */
export function OrbHeat({
  state = "still",
  speed = 1,
  colors,
  speeds,
  width,
  height,
  image,
  scale = 1,
  className,
}: OrbCharacterProps & {
  width: number
  height: number
  /** Asset FILE NAME (not a path) — resolved against the host's assetBase. */
  image?: string
  /** Shape scale within the frame — >1 pushes the rim toward the edges. */
  scale?: number
}) {
  const { params, palette } = useHeatEngine({ state, speed, speeds, colors })
  const hostRef = React.useRef<HTMLDivElement>(null)
  const epoch = useShaderEpoch(hostRef, palette.length > 0)
  const src = useAmbientAsset(image ?? CIRCLE_IMAGE)
  if (palette.length === 0) return null
  return (
    <div ref={hostRef} aria-hidden className={className}>
      <Heatmap
        key={epoch}
        width={width}
        height={height}
        image={src}
        colors={palette}
        colorBack="#00000000"
        contour={params.contour}
        angle={params.angle}
        noise={0}
        innerGlow={params.innerGlow}
        outerGlow={params.outerGlow}
        speed={params.speed}
        scale={scale}
        fit="contain"
      />
    </div>
  )
}

/** The field's shapes — near-full-bleed rounded rects in three aspect
    buckets, so the heat hugs every edge of wide, square, and tall
    surfaces (the loader rejects data URIs, so aspects are bucketed). */
function rectImageFor(w: number, h: number) {
  const ratio = w / h
  if (ratio > 1.4) return "orb-rect-wide.svg?v=3"
  if (ratio < 0.72) return "orb-rect-tall.svg?v=3"
  return "orb-rect.svg?v=4"
}

/**
 * OrbField — the orb's heat as a SURFACE BACKGROUND: the same engine and
 * states, wrapped around a rounded rect that fills the surface behind its
 * glass. One field per open AI surface (only one is ever open), mounted
 * a beat after the entrance so the shader compile can't jank it, fading
 * in on the surface role.
 */
export function OrbField({
  state = "still",
  speed = 1,
  colors,
  speeds,
  strength = "ambient",
  className,
}: OrbCharacterProps & {
  /**
   * "ambient" — a low-presence layer behind surface content (the default).
   * "stage" — the field IS the ground (the canvas page, projectors): full
   * presence, paired with the lighter .ambient-stage-frost.
   */
  strength?: "ambient" | "stage"
}) {
  const { params, palette } = useHeatEngine({ state, speed, speeds, colors })
  const hostRef = React.useRef<HTMLDivElement>(null)
  const epoch = useShaderEpoch(hostRef, palette.length > 0)
  const assetBase = useAmbientRuntime().assetBase
  const [box, setBox] = React.useState<{
    w: number
    h: number
    scale: number
  } | null>(null)
  const [ready, setReady] = React.useState(false)

  React.useEffect(() => {
    const t = window.setTimeout(() => setReady(true), 400)
    return () => window.clearTimeout(t)
  }, [])

  React.useEffect(() => {
    const el = hostRef.current
    if (!el) return
    const ro = new ResizeObserver(([entry]) => {
      const r = entry!.contentRect
      if (r.width <= 0 || r.height <= 0) return
      // RENDER RESOLUTION IS NOT LAYOUT SIZE. The field is a blurred
      // gradient stretched behind frosted glass, so its pixels carry no
      // detail — but at layout size on a retina display a full-page field
      // is millions of fragments per frame, which is what a shader costs.
      // Cap the long edge and let CSS scale it up; the result is identical
      // and the fragment load drops by an order of magnitude.
      const MAX = 360
      const shrink = Math.min(1, MAX / Math.max(r.width, r.height))
      setBox({
        w: Math.max(1, Math.round(r.width * shrink)),
        h: Math.max(1, Math.round(r.height * shrink)),
        scale: 1 / shrink,
      })
    })
    ro.observe(el)
    return () => ro.disconnect()
  }, [])

  return (
    <div
      ref={hostRef}
      aria-hidden
      className={cn(
        // Surfaces oversize the field so the shape's contour (and corners)
        // sit OUTSIDE the clip — only the glow bleeds in. A STAGE field is
        // the ground itself: keep the body in frame and amplify it so the
        // heat carries across a room.
        "pointer-events-none absolute transition-opacity duration-(--motion-surface) ease-(--motion-ease)",
        strength === "stage"
          // saturate only — brightness/contrast wash the ramp toward white,
          // which is exactly the color draining out of the ground
          ? "-inset-[4%] saturate-[1.5]"
          : "-inset-[14%]",
        // ambient light, not a flood — the field stays a low-presence layer
        // and the veil above does the rest
        ready && box && palette.length > 0
          ? strength === "stage"
            ? "opacity-100"
            : "opacity-35"
          : "opacity-0",
        className
      )}
    >
      {ready && box && palette.length > 0 && (
        <div
          className="absolute top-1/2 left-1/2"
          style={{
            width: box.w,
            height: box.h,
            // transform scales the PIXELS, not the layout — the shader keeps
            // sizing itself from this capped box while the visual covers the
            // whole surface (and overshoots it, so a surface that grows never
            // reveals an edge).
            transform: `translate(-50%, -50%) scale(${box.scale * 1.06})`,
            transformOrigin: "center",
          }}
        >
        <Heatmap
          key={epoch}
          width={box.w}
          height={box.h}
          image={`${assetBase.replace(/\/$/, "")}/${rectImageFor(box.w, box.h)}`}
          colors={palette}
          colorBack="#00000000"
          contour={params.contour}
          angle={params.angle}
          noise={0}
          innerGlow={params.innerGlow}
          outerGlow={params.outerGlow}
          speed={params.speed}
          scale={1}
          fit="cover"
        />
        </div>
      )}
    </div>
  )
}

export type { OrbState }

"use client"

import * as React from "react"

/**
 * THE ONE ORDERING RULE: an answer arrives in sequence, never all at once.
 *
 * Thinking finishes, THEN the next block does its work, THEN the prose
 * streams. Before this, every staged block ran its own private timer, so a
 * reasoning panel, a tool call and the answer text all raced — the sentence
 * explaining the work appeared while the work was still visibly spinning.
 * That reads as theatre, because it is: nothing was waiting on anything.
 *
 * The queue is a strict order, not a schedule. Each staged block claims a
 * slot in mount order and is held at its shimmer until every slot before it
 * has reported finished. `useStagedReveal` does the claiming, so a block
 * inherits the rule by being staged at all — there is nothing for an
 * individual block to remember, and nothing it can opt out of by accident.
 *
 * Outside a provider (a /ds playground, a lone block) `isTurn` is never
 * consulted and blocks stage immediately, which is the right behavior for a
 * block standing on its own.
 */

export type StageQueue = {
  register: (id: string) => void
  unregister: (id: string) => void
  finish: (id: string) => void
  /** True once every block that registered before `id` has finished. */
  isTurn: (id: string) => boolean
}

export const StageQueueContext = React.createContext<StageQueue | null>(null)

/**
 * Held by whatever owns the sequence (ResponseBlock). `settled` is the gate
 * for what comes AFTER the queue — the answer text waits on it.
 *
 * `expected` is how many blocks the owner actually rendered, and the gate is
 * counted against THAT rather than against the registration list. The list is
 * built from mount effects, so anything that perturbs it — a remount, a block
 * that leaves — could otherwise leave the gate waiting on a slot nobody is
 * standing in. The owner's count cannot drift: it is the array it mapped.
 */
export function useStageQueue(expected = 0) {
  // arrays, not Sets: the order IS the data, and a new array per change is
  // what makes `isTurn` recompute for the blocks waiting on it
  const [order, setOrder] = React.useState<string[]>([])
  const [done, setDone] = React.useState<string[]>([])

  const register = React.useCallback((id: string) => {
    setOrder((o) => (o.includes(id) ? o : [...o, id]))
  }, [])

  const unregister = React.useCallback((id: string) => {
    // a block that leaves must not hold the queue behind it forever
    setOrder((o) => o.filter((x) => x !== id))
    setDone((d) => d.filter((x) => x !== id))
  }, [])

  const finish = React.useCallback((id: string) => {
    setDone((d) => (d.includes(id) ? d : [...d, id]))
  }, [])

  const isTurn = React.useCallback(
    (id: string) => {
      const i = order.indexOf(id)
      // not registered yet: hold at the shimmer rather than jumping the line
      if (i < 0) return false
      return order.slice(0, i).every((x) => done.includes(x))
    },
    [order, done]
  )

  const queue = React.useMemo(
    () => ({ register, unregister, finish, isTurn }),
    [register, unregister, finish, isTurn]
  )

  return {
    queue,
    /** As many blocks have finished as the owner put in. */
    settled: expected > 0 && done.length >= expected,
  }
}

"use client"

import * as React from "react"

import { motion } from "framer-motion"

import { Skeleton } from "@/components/ui/skeleton"
import { cn } from "@/lib/utils"

import { useMotionTransition } from "./ambient-runtime"

/**
 * The two rendering halves of staged arrival; the hook that drives them is
 * use-staged-reveal.ts (a file that exports both a hook and components loses
 * Fast Refresh for everything importing it).
 */

/** The shimmer stand-in, sized to the rows it is standing in for. */
export function StageSkeleton({
  rows = 2,
  className,
}: {
  rows?: number
  className?: string
}) {
  return (
    <div className={cn("flex flex-col gap-2 pt-3", className)} aria-hidden>
      {Array.from({ length: rows }, (_, i) => (
        <div key={i} className="flex items-start gap-2.5">
          <Skeleton className="mt-1.5 size-1.5 rounded-full" />
          <div className="flex min-w-0 flex-1 flex-col gap-1.5">
            <Skeleton className="h-3 rounded-md" style={{ width: "38%" }} />
            <Skeleton
              className="h-3 rounded-md"
              style={{ width: i % 2 ? "72%" : "88%" }}
            />
          </div>
        </div>
      ))}
    </div>
  )
}

/**
 * One item landing. Subtle on purpose: this is reporting, not choreography.
 *
 * Height animates alongside opacity because the row below is what the eye is
 * actually resting on — a row that appears at full height shoves everything
 * under it in a single frame, and that jump reads as jank no matter how the
 * row itself fades. The outer div owns the reveal (height + clip), the inner
 * div owns the layout, so flex rows never fight the overflow clip.
 */
export function StagedItem({
  index = 0,
  children,
  className,
}: {
  index?: number
  children: React.ReactNode
  className?: string
}) {
  const transition = useMotionTransition("control")
  return (
    <motion.div
      initial={{ opacity: 0, height: 0 }}
      animate={{ opacity: 1, height: "auto" }}
      transition={transition}
      className="overflow-hidden"
      data-stage-index={index}
    >
      <motion.div
        initial={{ y: 6 }}
        animate={{ y: 0 }}
        transition={transition}
        className={className}
      >
        {children}
      </motion.div>
    </motion.div>
  )
}

/** The line a block shows while it is still working. */
export function StageLabel({
  children,
  className,
}: {
  children: React.ReactNode
  className?: string
}) {
  return (
    <span className={cn("ambient-shimmer text-sm", className)}>
      {children}
    </span>
  )
}

"use client"

import * as React from "react"

import { useAnimationFrame } from "framer-motion"


import { useAmbientRuntime } from "./ambient-runtime"

/**
 * STREAMING TEXT — text that arrives rather than appears.
 *
 * Three zones travel with the write head: settled text in the foreground,
 * a warm tail in the ambient accent, and a blurred edge behind a fading
 * mask. The reveal runs on the FRAME CLOCK, not a timer, and derives its
 * position from ELAPSED TIME rather than by counting ticks. A hidden tab
 * pauses the frame loop either way; what this buys is the recovery — coming
 * back, the write head is where the clock says it should be, instead of
 * however far a throttled timer happened to count.
 *
 * `live={false}` renders the whole string settled — history is written,
 * not replayed, so a re-rendered older message never re-types itself.
 */
/** How many characters trail behind the write head, warm then blurred. */
const TAIL = 26
const EDGE = 8

export function StreamingText({
  text,
  live = true,
  charsPerSecond,
  onSettled,
  className,
}: {
  text: string
  live?: boolean
  /**
   * Override the runtime pace (streamCharsPerSecond). The
   * default reads as deliberate writing, not a printer.
   */
  charsPerSecond?: number
  onSettled?: () => void
  className?: string
}) {
  // THE COMPONENT-LAYER CONFIG: the pace is a saved product decision, so the
  // prop is an override, not the source of truth. Same rule as the orb's
  // palette — the rail edits the theme, the theme drives every instance.
  const runtime = useAmbientRuntime()
  const cps = charsPerSecond ?? runtime.streamCharsPerSecond
  const [shown, setShown] = React.useState(() => (live ? 0 : text.length))
  const settledRef = React.useRef(!live)
  const onSettledRef = React.useRef(onSettled)
  // the frame loop calls this without re-subscribing; refreshed after commit
  React.useEffect(() => {
    onSettledRef.current = onSettled
  })
  const startRef = React.useRef<number | null>(null)

  useAnimationFrame((t) => {
    if (settledRef.current || !live) return
    if (startRef.current === null) startRef.current = t
    const next = Math.min(
      text.length,
      Math.floor(((t - startRef.current) / 1000) * cps)
    )
    setShown(next)
    if (next >= text.length) {
      settledRef.current = true
      window.setTimeout(() => onSettledRef.current?.(), 400)
    }
  })

  const done = shown >= text.length

  return (
    <span className={className}>
      {text.slice(0, done ? text.length : Math.max(0, shown - TAIL))}
      {!done && (
        <>
          <span className="ambient-stream-warm">
            {text.slice(Math.max(0, shown - TAIL), Math.max(0, shown - EDGE))}
          </span>
          <span className="ambient-stream-edge">
            {text.slice(Math.max(0, shown - EDGE), shown)}
          </span>
          <span className="bg-primary ms-0.5 inline-block h-3.5 w-0.5 animate-pulse align-middle" />
        </>
      )}
    </span>
  )
}

"use client"

import * as React from "react"

import { StageQueueContext } from "./stage-queue"

/**
 * STAGED ARRIVAL — how every evidence block admits that it took time.
 *
 * A reasoning trace, a batch of tool calls, a list of sources: all of them
 * arrive complete in the code and would paint in one frame. Painting them
 * instantly is a small lie — it says the work was free — and it also robs the
 * reader of the one thing the block is for, which is watching the assistant
 * think.
 *
 * So every block stages the same way:
 *
 *   1. SHIMMER while there is nothing yet. The placeholder carries the
 *      ambient accent (see .ambient-shimmer), so waiting is the assistant's
 *      identity rather than generic grey.
 *   2. HOLD, because a beat of nothing is what makes the arrival read as an
 *      arrival.
 *   3. ONE AT A TIME, each item on the control motion role.
 *
 * And blocks wait for EACH OTHER: inside a response the hook claims a slot in
 * the stage queue and holds at its shimmer until every earlier block has
 * finished (see stage-queue.ts). Thinking completes, then the next block
 * works, then the answer streams — one sequence rather than a race.
 *
 * This lives in one place so the blocks cannot drift into three different
 * ideas of what waiting looks like.
 */

export interface StageOptions {
  /** How long the shimmer holds before the first item lands. */
  delay?: number
  /** Gap between items. */
  interval?: number
  /** Pass false to render settled — history is written, not replayed. */
  enabled?: boolean
  /** Bump to perform the arrival again — a re-run is a new arrival. */
  replay?: number
  /**
   * Hold the working state for at least this long, even after every item has
   * landed. Thinking that finishes in a blink reads as a lookup, not as work
   * — and because the hold is REAL, the counter measuring it stays honest.
   */
  minDuration?: number
}

/**
 * Returns how many of `count` items should be visible, and whether the block
 * is still in its shimmer. Settled when `enabled` is false, so a re-rendered
 * older message never performs its arrival again.
 */
export function useStagedReveal(count: number, options: StageOptions = {}) {
  const {
    delay = 700,
    interval = 320,
    enabled = true,
    replay = 0,
    minDuration = 0,
  } = options
  const [shown, setShown] = React.useState(enabled ? 0 : count)

  // THE QUEUE. A slot is claimed on mount, so slots are handed out in mount
  // order — which for the sibling blocks of one answer is reading order. With
  // no provider above (a /ds playground, a lone block) there is no queue and
  // the block simply stages.
  const queue = React.useContext(StageQueueContext)
  const id = React.useId()
  // Depend on the CALLBACKS, never on the queue object: its identity changes
  // every time any block registers or finishes (isTurn closes over the
  // order), so an effect keyed on it would unregister and re-register this
  // block on every change — shuffling it to the back of a line it is already
  // standing in, forever.
  const register = queue?.register
  const unregister = queue?.unregister
  React.useEffect(() => {
    if (!register || !unregister) return
    register(id)
    return () => unregister(id)
  }, [register, unregister, id])
  const waiting = enabled && Boolean(queue) && !queue!.isTurn(id)
  // running = this block's turn has come AND it stages at all
  const running = enabled && !waiting

  // A changed input starts the arrival over. Adjusted DURING render, not from
  // an effect: resetting to 0 after the fact paints one frame of the finished
  // list before the shimmer.
  const scope = `${count}|${delay}|${interval}|${running}|${replay}|${minDuration}`
  const [floorMet, setFloorMet] = React.useState(!minDuration)
  const [scopeSeen, setScopeSeen] = React.useState(scope)
  if (scope !== scopeSeen) {
    setScopeSeen(scope)
    setShown(enabled ? 0 : count)
    setFloorMet(!minDuration)
  }

  React.useEffect(() => {
    if (!running || !minDuration) return
    const id = window.setTimeout(() => setFloorMet(true), minDuration)
    return () => window.clearTimeout(id)
  }, [scope, running, minDuration])

  React.useEffect(() => {
    if (!running) return
    const timers: number[] = []
    for (let i = 0; i < count; i++) {
      timers.push(
        window.setTimeout(() => setShown(i + 1), delay + i * interval)
      )
    }
    return () => timers.forEach(window.clearTimeout)
  }, [scope, count, delay, interval, running])

  // hand the queue on the moment this block has nothing left to reveal — a
  // settled block (enabled false) was never in the running, so it yields at once
  const complete = !enabled || (shown >= count && floorMet)
  const finish = queue?.finish
  React.useEffect(() => {
    if (finish && complete) finish(id)
  }, [finish, complete, id])

  return {
    shown,
    pending: shown === 0,
    /** Holding for an earlier block. Shimmering, but not yet working. */
    waiting,
    /**
     * Actually producing something right now — its turn has come and it has
     * items left to reveal. THIS is what an elapsed counter runs on: false
     * while queued (someone else's time) and false once complete (so the
     * settled summary quotes a measurement that has stopped moving).
     */
    working: running && (shown < count || !floorMet),
  }
}

/**
 * Seconds elapsed since `active` became true, ticking once a second.
 *
 * Pass the block's WORKING flag, never just `staged`: a block held in the
 * stage queue is not working yet, and a counter that ran through the wait
 * would quote someone else's time as its own.
 *
 * The count is REAL: a trace that claims "thought for 5s" while it took two is
 * a decoration pretending to be a measurement. It freezes at the final value
 * when the work ends, which is the number the settled summary then quotes.
 */
export function useElapsedSeconds(active: boolean) {
  const [elapsed, setElapsed] = React.useState(0)
  const startedRef = React.useRef<number | null>(null)

  React.useEffect(() => {
    if (!active) return
    startedRef.current = performance.now()
    const id = window.setInterval(() => {
      const started = startedRef.current
      if (started !== null) setElapsed(Math.round((performance.now() - started) / 1000))
    }, 250)
    return () => window.clearInterval(id)
  }, [active])

  return elapsed
}
